insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('f8000000-0000-0000-0000-000000000001', 'mrcp1', '0e353931-7fcd-45ab-ab0f-3ad235bddc57',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('f8000000-0000-0000-0000-000000000001', 'A', 'Add a weak opioid (e.g. codeine) to the paracetamol', true, 'Correct. Following the WHO analgesic ladder, when non-opioid analgesia (step 1, e.g. paracetamol) is insufficient for mild-to-moderate pain, a weak opioid (step 2, e.g. codeine or tramadol) is added, continuing the non-opioid alongside it, before escalating to a strong opioid if pain remains uncontrolled.', 1),
('f8000000-0000-0000-0000-000000000001', 'B', 'Immediately start a strong opioid (e.g. morphine)', false, 'Ruled out because the WHO ladder recommends a stepwise approach; strong opioids (step 3) are reserved for moderate-to-severe pain not controlled by step 1 or 2 measures, not jumping directly from paracetamol alone for mild-to-moderate pain.', 2),
('f8000000-0000-0000-0000-000000000001', 'C', 'Stop paracetamol and switch to an NSAID alone', false, 'Ruled out because this does not follow the stepwise WHO ladder approach of adding, not switching, a step 2 agent; also, NSAID use requires specific consideration of risks (GI, renal, cardiovascular) in this patient population.', 3),
('f8000000-0000-0000-0000-000000000001', 'D', 'No further analgesia is needed, as this level of pain is expected in cancer', false, 'Ruled out because uncontrolled pain should always be actively addressed and is not something to be accepted as an inevitable consequence of cancer; effective analgesia is achievable and should be pursued.', 4),
('f8000000-0000-0000-0000-000000000001', 'E', 'Refer for immediate palliative sedation', false, 'Ruled out because this is a vastly disproportionate response to mild-to-moderate, currently step-1-managed pain; palliative sedation is reserved for specific, severe, refractory symptoms at the end of life, not as an early step in routine pain management.', 5),
('f8000000-0000-0000-0000-000000000002', 'A', 'Simply increase the codeine dose indefinitely', false, 'Ruled out because codeine has a ceiling effect beyond which further dose increases provide diminishing analgesic benefit with increasing side effects; moving to a strong opioid is the appropriate step rather than continuing to escalate a weak opioid indefinitely.', 1),
('f8000000-0000-0000-0000-000000000002', 'B', 'Stop all analgesia and try non-pharmacological measures alone', false, 'Ruled out because although non-pharmacological measures can be valuable adjuncts, stopping all analgesia for moderate-to-severe cancer pain would leave her inadequately treated; pharmacological escalation remains the priority.', 2),
('f8000000-0000-0000-0000-000000000002', 'C', 'Refer for immediate palliative sedation', false, 'Ruled out because this is a disproportionate response to pain that has not yet had an adequate trial of standard step 3 (strong opioid) treatment; palliative sedation is reserved for specific, refractory end-of-life symptoms, not as an early pain management step.', 3),
('f8000000-0000-0000-0000-000000000002', 'D', 'Add a second weak opioid alongside the codeine', false, 'Ruled out because combining two weak opioids does not provide meaningfully greater analgesic benefit and is not standard practice; moving to a strong opioid is the appropriate escalation.', 4),
('f8000000-0000-0000-0000-000000000002', 'E', 'Switch to a strong opioid (e.g. oral morphine), continuing paracetamol', true, 'Correct. When pain remains moderate-to-severe despite an adequate trial of a weak opioid, the WHO ladder recommends moving to step 3, starting a strong opioid (commonly oral morphine, titrated according to response), while continuing the non-opioid (paracetamol) alongside it.', 5),
('f8000000-0000-0000-0000-000000000003', 'A', 'Simply increasing the opioid dose further, with no other change', false, 'Ruled out because neuropathic pain often responds poorly to opioid dose escalation alone, and adjuvant, mechanism-targeted treatment is more likely to provide additional benefit than continuing to increase opioid dose without addressing the specific pain mechanism.', 1),
('f8000000-0000-0000-0000-000000000003', 'B', 'Switching to a purely non-opioid analgesic regimen', false, 'Ruled out because opioids likely still have some role in his overall pain management (particularly for the nociceptive component of his pain); the more appropriate step is adding an adjuvant for the neuropathic component, not necessarily stopping opioids entirely.', 2),
('f8000000-0000-0000-0000-000000000003', 'C', 'No further treatment options exist for this pain', false, 'Ruled out because effective adjuvant treatments specifically exist for neuropathic pain and should be actively considered and trialled, rather than concluding no further options are available.', 3),
('f8000000-0000-0000-0000-000000000003', 'D', 'Neuropathic pain component, requiring addition of an adjuvant analgesic (e.g. a gabapentinoid or tricyclic antidepressant)', true, 'Correct. Burning pain with allodynia, poorly responsive to opioids alone, suggests a significant neuropathic pain component (here likely from tumour infiltration of nerve structures, e.g. the coeliac plexus); adjuvant analgesics specifically targeting neuropathic pain (gabapentinoids such as gabapentin or pregabalin, or tricyclic antidepressants such as amitriptyline) are added alongside opioids, as neuropathic pain often responds only partially to opioids alone.', 4),
('f8000000-0000-0000-0000-000000000003', 'E', 'Referral for immediate palliative sedation', false, 'Ruled out because this represents a disproportionate response when standard adjuvant analgesic options for neuropathic pain have not yet been tried; palliative sedation is reserved for specific, refractory symptoms at the end of life.', 5),
('f8000000-0000-0000-0000-000000000004', 'A', 'Increasing the modified-release background dose alone, without any breakthrough medication', false, $x$Ruled out because while background dose adjustment may sometimes be needed based on overall pain patterns, specific breakthrough pain episodes require a fast-acting 'as-needed' medication for prompt relief, not simply increasing the slower-acting background dose alone.$x$, 1),
('f8000000-0000-0000-0000-000000000004', 'B', $x$Immediate-release morphine, prescribed as an 'as-needed' dose for breakthrough pain$x$, true, 'Correct. Breakthrough pain (transient flares occurring despite adequate background analgesia) is managed with a fast-acting, immediate-release formulation of the same opioid used for background control, typically dosed at approximately one-sixth of the total daily background opioid dose, available for use as needed alongside the regular modified-release background medication.', 2),
('f8000000-0000-0000-0000-000000000004', 'C', 'Stopping the modified-release opioid and using only as-needed doses', false, 'Ruled out because background pain control still requires a regular, sustained analgesic approach (modified-release opioid); breakthrough medication is an addition to, not a replacement for, effective background control.', 3),
('f8000000-0000-0000-0000-000000000004', 'D', 'A different class of medication entirely, unrelated to opioids', false, 'Ruled out because breakthrough opioid pain is typically managed with an immediate-release formulation of the same opioid class already providing background control, not switching to an unrelated medication class.', 4),
('f8000000-0000-0000-0000-000000000004', 'E', 'No specific treatment for breakthrough episodes, as they should simply be tolerated', false, 'Ruled out because breakthrough pain is a recognised, treatable phenomenon with an established management approach (immediate-release opioid), not something patients should simply be expected to endure without specific treatment.', 5),
('f8000000-0000-0000-0000-000000000005', 'A', 'Standard-dose morphine, with no need for any adjustment', false, 'Ruled out because standard morphine dosing in significant renal impairment risks toxic accumulation of active metabolites, requiring either dose reduction/increased dosing interval or, more commonly, choice of an alternative opioid better suited to renal impairment.', 1),
('f8000000-0000-0000-0000-000000000005', 'B', 'Avoiding all opioid analgesia due to his renal impairment', false, 'Ruled out because effective pain relief remains important and achievable in renal impairment; the approach is careful opioid selection and dose adjustment, not avoiding opioid analgesia altogether when clinically indicated.', 2),
('f8000000-0000-0000-0000-000000000005', 'C', 'A opioid with reduced accumulation risk in renal impairment (e.g. oxycodone with caution and dose reduction, alfentanil, or fentanyl), avoiding standard morphine dosing', true, $x$Correct. Morphine's active metabolites (particularly morphine-6-glucuronide) accumulate in significant renal impairment, increasing the risk of toxicity (sedation, respiratory depression); alternative opioids with less problematic accumulation in renal impairment (such as oxycodone used cautiously with dose reduction, or opioids like alfentanil/fentanyl that are less renally dependent for clearance) are generally preferred, with specialist palliative care input often valuable in this context.$x$, 3),
('f8000000-0000-0000-0000-000000000005', 'D', 'High-dose NSAID therapy as the primary strong analgesic instead of an opioid', false, 'Ruled out because NSAIDs are relatively contraindicated in significant renal impairment due to further nephrotoxicity risk, and are not a substitute for appropriately chosen strong opioid analgesia for moderate-to-severe pain.', 4),
('f8000000-0000-0000-0000-000000000005', 'E', 'Doubling the standard morphine dose to overcome reduced efficacy', false, 'Ruled out because the concern in renal impairment is not reduced morphine efficacy but rather accumulation of active metabolites causing toxicity; doubling the dose would worsen, not address, this risk.', 5),
('f8000000-0000-0000-0000-000000000006', 'A', 'No specific action needed, as this will resolve on its own over time', false, 'Ruled out because, unlike sedation and nausea (to which tolerance typically develops within days), tolerance to opioid-induced constipation does not reliably develop, meaning ongoing, active laxative management is needed for as long as opioid therapy continues.', 1),
('f8000000-0000-0000-0000-000000000006', 'B', 'Regular prophylactic laxative therapy, continued alongside ongoing opioid treatment', true, 'Correct. Opioid-induced constipation is a very common, predictable side effect (unlike most other opioid side effects, tolerance to this effect does not typically develop over time), so regular prophylactic laxative therapy (typically combining a stimulant and softener, or as per local protocol) should be co-prescribed from the outset of opioid therapy and continued throughout treatment, not simply addressed reactively once constipation has already become established.', 2),
('f8000000-0000-0000-0000-000000000006', 'C', 'Stopping the opioid immediately due to this side effect', false, 'Ruled out because opioid-induced constipation is a manageable side effect with appropriate laxative therapy, not typically a reason to stop otherwise effective and needed analgesia.', 3),
('f8000000-0000-0000-0000-000000000006', 'D', 'Fibre supplementation alone, without other laxatives', false, 'Ruled out because fibre supplementation alone is generally insufficient and can sometimes worsen symptoms in opioid-induced constipation if adequate fluid intake is not maintained; a combination of laxatives (typically stimulant plus softener) is the standard, more effective approach.', 4),
('f8000000-0000-0000-0000-000000000006', 'E', 'Reducing fluid intake to manage the constipation', false, 'Ruled out because reducing fluid intake would worsen, not improve, constipation; adequate hydration is supportive, though laxative therapy remains the primary specific treatment.', 5),
('f8000000-0000-0000-0000-000000000007', 'A', 'Simple disease progression requiring further opioid dose escalation', false, 'Ruled out because although disease progression is always a differential to consider, the specific combination of worsening pain with dose escalation, allodynia and myoclonus is characteristic of opioid-induced hyperalgesia, where further dose escalation would worsen rather than improve the situation.', 1),
('f8000000-0000-0000-0000-000000000007', 'B', 'A simple allergic reaction to the opioid', false, 'Ruled out because this does not describe a typical allergic reaction pattern; the specific combination of worsening pain with dose escalation, allodynia and myoclonus is characteristic of opioid-induced hyperalgesia/toxicity.', 2),
('f8000000-0000-0000-0000-000000000007', 'C', 'Opioid-induced hyperalgesia, a paradoxical increase in pain sensitivity from high-dose/escalating opioid therapy', true, 'Correct. Opioid-induced hyperalgesia is a recognised phenomenon in which high-dose or rapidly escalating opioid therapy paradoxically increases pain sensitivity (allodynia, worsening pain despite dose increases), often accompanied by other signs of opioid toxicity such as myoclonus; management typically involves opioid dose reduction, opioid switching (rotation), or use of adjuvant agents, rather than further dose escalation, which would worsen the hyperalgesia.', 3),
('f8000000-0000-0000-0000-000000000007', 'D', 'Successful pain control requiring no further changes', false, 'Ruled out because this scenario specifically describes worsening, not improving, pain control, along with concerning additional features (myoclonus) indicating toxicity requiring active management, not a successful outcome requiring no changes.', 4),
('f8000000-0000-0000-0000-000000000007', 'E', 'Simple opioid tolerance requiring straightforward further dose increases', false, 'Ruled out because although tolerance can occur, the specific pattern described (worsening pain with escalating doses, plus allodynia and myoclonus) is more consistent with hyperalgesia/toxicity than simple tolerance, and further dose escalation would be inappropriate and potentially harmful in this context.', 5),
('f8000000-0000-0000-0000-000000000008', 'A', 'Further systemic opioid dose escalation alone, without any localised treatment', false, 'Ruled out because although systemic analgesia remains important for overall pain control, localised radiotherapy specifically and effectively targets the pain from a discrete metastatic site, often providing better site-specific relief than opioid escalation alone, while also reducing local fracture risk.', 1),
('f8000000-0000-0000-0000-000000000008', 'B', 'Immediate amputation of the affected limb', false, 'Ruled out because this is a vastly disproportionate treatment for a bone metastasis without current fracture; radiotherapy is the appropriate, far less invasive, effective localised treatment option.', 2),
('f8000000-0000-0000-0000-000000000008', 'C', 'No specific localised treatment is available for bone metastases', false, 'Ruled out because radiotherapy is a well-established, effective, specific treatment for painful bone metastases, directly contradicting this statement.', 3),
('f8000000-0000-0000-0000-000000000008', 'D', 'Palliative radiotherapy to the affected site', true, 'Correct. Localised radiotherapy is a highly effective treatment for pain from a discrete bone metastasis, often providing significant, sometimes complete, pain relief at the treated site, used as an adjunct to (and sometimes allowing reduction of) systemic analgesia, alongside its role in reducing the risk of pathological fracture at the site.', 4),
('f8000000-0000-0000-0000-000000000008', 'E', 'Physiotherapy alone, without any medical or oncological treatment', false, 'Ruled out because although physiotherapy may have a supportive role, it does not address the underlying tumour-related pain and fracture risk in the way that targeted radiotherapy does.', 5),
('f8000000-0000-0000-0000-000000000009', 'A', 'Opioids should be started at a lower dose with careful titration, given reduced hepatic metabolism increasing the risk of accumulation and toxicity', true, 'Correct. Significant hepatic impairment can reduce the metabolism and clearance of many opioids, increasing the risk of drug accumulation and toxicity (sedation, respiratory depression); opioids should be started at a lower dose with careful, cautious titration and close monitoring in this context, often with specialist palliative care input given the complexity.', 1),
('f8000000-0000-0000-0000-000000000009', 'B', 'No dose adjustment is needed regardless of hepatic function', false, 'Ruled out because significant hepatic impairment can meaningfully alter opioid metabolism and clearance, making dose caution and careful titration important, not proceeding with standard, unadjusted dosing.', 2),
('f8000000-0000-0000-0000-000000000009', 'C', 'Opioids should be avoided entirely in any degree of liver disease', false, 'Ruled out because opioids can still be used effectively and safely in hepatic impairment with appropriate caution (lower starting doses, careful titration, monitoring); complete avoidance is not necessary or appropriate when analgesia is clinically needed.', 3),
('f8000000-0000-0000-0000-000000000009', 'D', 'Doubling the standard starting dose to ensure adequate effect', false, 'Ruled out because this is the opposite of the appropriate approach; reduced hepatic metabolism increases toxicity risk at standard or higher doses, meaning lower, not higher, starting doses are appropriate.', 4),
('f8000000-0000-0000-0000-000000000009', 'E', 'Only paracetamol should ever be used in hepatic impairment, with opioids entirely avoided', false, 'Ruled out because although paracetamol dosing also requires caution in significant hepatic impairment (given its own hepatic metabolism), opioids remain an appropriate option for moderate-to-severe pain when used with the described careful, cautious approach, not one to be entirely avoided in favour of paracetamol alone.', 5),
('f8000000-0000-0000-0000-000000000010', 'A', 'Simple malingering, as her pain is exaggerated by non-physical factors', false, 'Ruled out because this framing is inappropriate and unhelpful; the total pain concept recognises that psychological and social factors genuinely influence and amplify the real experience of pain, rather than implying the pain itself is fabricated or exaggerated dishonestly.', 1),
('f8000000-0000-0000-0000-000000000010', 'B', 'Pure neuropathic pain requiring only adjuvant analgesic treatment', false, 'Ruled out because this description reflects a multidimensional pain experience involving psychological and existential factors, not simply a neuropathic pain mechanism requiring only pharmacological adjuvant treatment.', 2),
('f8000000-0000-0000-0000-000000000010', 'C', 'An unrelated anxiety disorder requiring psychiatric referral instead of pain management', false, 'Ruled out because although psychological support is an important component of addressing total pain, this is not simply an unrelated anxiety disorder to be referred elsewhere instead of holistic pain management; the anxiety and pain are interconnected within this concept.', 3),
('f8000000-0000-0000-0000-000000000010', 'D', 'A sign that her physical pain control is inadequate and requires opioid escalation alone', false, 'Ruled out because although physical pain control should be reviewed, simply escalating opioids would not adequately address the psychological, social and spiritual dimensions contributing to her overall distress, which require their own specific attention alongside physical symptom management.', 4),
('f8000000-0000-0000-0000-000000000010', 'E', 'Total pain, encompassing physical, psychological, social and spiritual dimensions', true, $x$Correct. The concept of 'total pain,' developed within palliative care, recognises that the experience of pain in serious illness is multidimensional, encompassing not only physical nociceptive/neuropathic factors but also psychological distress, social concerns, and spiritual/existential suffering, all of which can amplify the perceived pain experience and require holistic assessment and management addressing each relevant dimension.$x$, 5),
('f8000000-0000-0000-0000-000000000011', 'A', 'Further, unlimited systemic opioid dose escalation alone, with no interventional option considered', false, 'Ruled out because when pain is genuinely opioid-refractory or requires very high doses with significant side effects, interventional techniques like coeliac plexus block offer an important complementary or alternative approach specifically suited to this pain mechanism and location.', 1),
('f8000000-0000-0000-0000-000000000011', 'B', 'Immediate surgical resection of the coeliac plexus as first-line treatment', false, 'Ruled out because surgical resection is not the standard interventional approach; percutaneous or endoscopic-guided chemical neurolysis (coeliac plexus block) is the established, less invasive technique used for this indication.', 2),
('f8000000-0000-0000-0000-000000000011', 'C', 'Coeliac plexus block (neurolysis)', true, 'Correct. For severe, opioid-refractory pain from pancreatic cancer specifically related to coeliac plexus infiltration, a coeliac plexus block (chemical neurolysis of the coeliac plexus) is an effective interventional technique, often providing significant pain relief and allowing reduction of systemic opioid requirements and their associated side effects.', 3),
('f8000000-0000-0000-0000-000000000011', 'D', 'Amputation-level surgery unrelated to the actual pain source', false, 'Ruled out because this is entirely inappropriate and unrelated to the specific pain mechanism (coeliac plexus infiltration) described.', 4),
('f8000000-0000-0000-0000-000000000011', 'E', 'No specific interventional options exist for this type of pain', false, 'Ruled out because coeliac plexus block is a well-established, specific interventional technique for exactly this clinical scenario (pancreatic cancer pain from coeliac plexus involvement), directly contradicting this statement.', 5),
('f8000000-0000-0000-0000-000000000012', 'A', 'Transdermal fentanyl has a slow onset and offset of action, requiring careful planning around the switch and unsuitability for rapid dose titration', true, 'Correct. Transdermal fentanyl patches have a slow onset of action (taking many hours to reach steady-state analgesic effect after application) and an equally slow offset (continuing to release drug for many hours after removal, with a depot effect in the skin), making them unsuitable for rapid dose titration and requiring careful planning when switching to or from this route, including appropriate overlap with prior analgesia during initiation.', 1),
('f8000000-0000-0000-0000-000000000012', 'B', 'Transdermal fentanyl acts immediately upon patch application, allowing rapid titration', false, 'Ruled out because this is the opposite of its actual pharmacokinetic profile; the slow onset is a key practical consideration, not a rapid-acting property.', 2),
('f8000000-0000-0000-0000-000000000012', 'C', 'Transdermal fentanyl has no specific practical considerations different from oral opioids', false, 'Ruled out because the transdermal route has specific, clinically important pharmacokinetic differences (slow onset/offset, depot effect) that require particular attention, unlike this statement suggests.', 3),
('f8000000-0000-0000-0000-000000000012', 'D', 'Patches should be changed every 24 hours regardless of the specific product used', false, $x$Ruled out because standard fentanyl patches are typically changed every 72 hours (per product-specific licensing), not daily; following the specific product's licensed dosing interval is important for appropriate, safe use.$x$, 4),
('f8000000-0000-0000-0000-000000000012', 'E', 'This route is only appropriate for patients with completely stable, well-established pain, and never used with breakthrough medication', false, 'Ruled out because while stable background pain is well suited to this route, breakthrough pain medication (typically a different, fast-acting formulation) is still needed and used alongside transdermal patches for any breakthrough pain episodes, similar to other opioid formulations.', 5),
('f8000000-0000-0000-0000-000000000013', 'A', 'Start immediately at a very high dose to ensure rapid, complete pain control', false, 'Ruled out because starting at a high dose risks significant side effects and toxicity, particularly in opioid-naive patients; a lower starting dose with careful titration is the standard, safer approach.', 1),
('f8000000-0000-0000-0000-000000000013', 'B', 'Start at a relatively low dose of an immediate-release opioid, with regular review and gradual upward titration guided by pain response and side effects', true, 'Correct. Standard practice for initiating strong opioid therapy is to start with a relatively low dose of an immediate-release preparation, allowing assessment of response and tolerability, with regular review and gradual upward titration based on ongoing pain control and any side effects, before considering conversion to a modified-release formulation once the effective dose is established.', 2),
('f8000000-0000-0000-0000-000000000013', 'C', 'Start with a modified-release formulation only, without any immediate-release component available', false, 'Ruled out because starting with an immediate-release preparation (allowing more flexible, responsive titration and providing a basis for calculating breakthrough dosing) is generally preferred initially, with conversion to modified-release once an effective, stable dose is established.', 3),
('f8000000-0000-0000-0000-000000000013', 'D', 'No titration is needed; a fixed standard dose is used for all patients regardless of response', false, 'Ruled out because opioid requirements vary significantly between individuals, making careful, individualised titration based on response essential, rather than applying a fixed dose to all patients regardless of their specific pain control and tolerability.', 4),
('f8000000-0000-0000-0000-000000000013', 'E', 'Opioids should never be started without first trialling every possible non-pharmacological option', false, 'Ruled out because although non-pharmacological measures can be valuable adjuncts, they should not delay appropriate pharmacological pain management when clinically indicated for significant pain.', 5),
('f8000000-0000-0000-0000-000000000014', 'A', 'Cyclizine regardless of the likely mechanism', false, 'Ruled out because cyclizine is more specifically suited to nausea with a vestibular or raised intracranial pressure mechanism; selecting an antiemetic based on the most likely underlying mechanism (here, more chemically/metabolically mediated) is the recommended approach rather than a one-size-fits-all default choice.', 1),
('f8000000-0000-0000-0000-000000000014', 'B', 'No antiemetic is appropriate until every possible cause has been exhaustively investigated', false, 'Ruled out because while identifying an underlying cause is valuable, empirical, mechanism-based antiemetic treatment is appropriate to provide symptomatic relief without requiring exhaustive investigation of every possible cause before treating.', 2),
('f8000000-0000-0000-0000-000000000014', 'C', 'High-dose opioids as the primary treatment for nausea', false, 'Ruled out because opioids themselves can cause nausea, and increasing the opioid dose would not address this symptom and could worsen it; a specific antiemetic is the appropriate treatment.', 3),
('f8000000-0000-0000-0000-000000000014', 'D', 'Haloperidol, targeting a likely chemically-mediated (chemoreceptor trigger zone) mechanism', true, 'Correct. When metabolic causes (e.g. hypercalcaemia) and opioid-timing-related nausea have been reasonably excluded, haloperidol (a dopamine antagonist acting at the chemoreceptor trigger zone) is a commonly used first-line antiemetic for nausea presumed to have a chemical/metabolic-type mechanism in palliative care, reflecting the principle of choosing an antiemetic based on the likely underlying mechanism of the nausea.', 4),
('f8000000-0000-0000-0000-000000000014', 'E', 'Simple reassurance with no active treatment', false, 'Ruled out because persistent, distressing nausea should be actively treated, not simply managed with reassurance alone, given effective treatment options exist.', 5),
('f8000000-0000-0000-0000-000000000015', 'A', 'Haloperidol as the definitive first-line choice regardless of the obstruction mechanism', false, 'Ruled out because although haloperidol can still play a role, the specific mechanism here (gastric stasis/obstruction-related nausea) makes a prokinetic-considered approach (with the described cautions) particularly relevant to discuss, rather than defaulting to haloperidol without considering the specific mechanism.', 1),
('f8000000-0000-0000-0000-000000000015', 'B', 'High-dose opioids as the primary antiemetic treatment', false, 'Ruled out because opioids are not antiemetics and can themselves contribute to nausea and reduced gut motility; they are not the appropriate treatment choice for this specific symptom.', 2),
('f8000000-0000-0000-0000-000000000015', 'C', 'No antiemetic treatment is possible in bowel obstruction', false, 'Ruled out because antiemetic treatment, carefully selected based on the specific obstruction characteristics (complete versus partial/functional), remains an important and achievable part of symptom management in malignant bowel obstruction.', 3),
('f8000000-0000-0000-0000-000000000015', 'D', 'Simple dietary modification alone, without any pharmacological treatment', false, 'Ruled out because pharmacological antiemetic treatment, alongside other measures, is an important part of managing nausea in this context, not dietary modification alone.', 4),
('f8000000-0000-0000-0000-000000000015', 'E', 'Metoclopramide, given its prokinetic action (with caution regarding its use in complete mechanical obstruction)', true, 'Correct. Metoclopramide has both antiemetic and prokinetic properties, making it useful for nausea related to gastric stasis; however, in complete mechanical bowel obstruction, prokinetic agents are used with caution (or avoided) due to the theoretical risk of worsening colic/pain by increasing gut motility against a complete mechanical block, requiring careful clinical assessment of whether the obstruction is complete or partial/functional before use.', 5),
('f8000000-0000-0000-0000-000000000016', 'A', 'Low-dose oral opioid (e.g. low-dose morphine)', true, 'Correct. Low-dose opioids have evidence for reducing the sensation of breathlessness in patients with advanced disease and refractory dyspnoea, working through central mechanisms to reduce the perceived respiratory effort/distress, used at doses typically lower than those needed for pain control, alongside continued optimal treatment of any underlying reversible causes and non-pharmacological measures (e.g. fan therapy, breathing techniques).', 1),
('f8000000-0000-0000-0000-000000000016', 'B', 'High-dose benzodiazepines as first-line treatment for breathlessness', false, 'Ruled out because benzodiazepines are not first-line for breathlessness itself; they may have an adjunctive role if significant anxiety is contributing, but low-dose opioids have stronger evidence as the primary pharmacological option for refractory dyspnoea.', 2),
('f8000000-0000-0000-0000-000000000016', 'C', 'High-flow oxygen regardless of oxygen saturation levels', false, 'Ruled out because oxygen therapy is specifically beneficial for hypoxaemic patients; in the absence of significant hypoxaemia, oxygen has not been shown to provide the same symptomatic benefit for breathlessness, and low-dose opioids are the more evidence-based pharmacological approach for symptom relief in this context.', 3),
('f8000000-0000-0000-0000-000000000016', 'D', 'No pharmacological options exist for breathlessness in this context', false, 'Ruled out because low-dose opioids specifically have evidence supporting their use for refractory breathlessness in advanced disease, directly contradicting this statement.', 4),
('f8000000-0000-0000-0000-000000000016', 'E', 'Antibiotics as the primary treatment, assuming an infective cause', false, 'Ruled out because there is no indication of an acute infective exacerbation described; this scenario describes chronic, refractory breathlessness despite optimised background treatment, for which low-dose opioids are an appropriate symptomatic option.', 5),
('f8000000-0000-0000-0000-000000000017', 'A', 'Aggressive deep suctioning as the primary intervention', false, 'Ruled out because aggressive suctioning is generally not recommended as first-line management, as it can be distressing/uncomfortable for the patient and is often only partially and temporarily effective, given ongoing secretion production; anticholinergic medication and repositioning are the preferred initial approaches.', 1),
('f8000000-0000-0000-0000-000000000017', 'B', 'No intervention or explanation is needed, as this symptom is irrelevant', false, 'Ruled out because although the patient is often not distressed by this symptom themselves, addressing it (both pharmacologically and through family reassurance/explanation) remains an important part of holistic end-of-life care, given how distressing it can be to witness for family and carers.', 2),
('f8000000-0000-0000-0000-000000000017', 'C', 'High-dose opioids specifically to treat the secretions', false, 'Ruled out because opioids do not specifically address respiratory secretions; anticholinergic medication is the more directly relevant pharmacological treatment for this particular symptom.', 3),
('f8000000-0000-0000-0000-000000000017', 'D', 'Immediate transfer to intensive care for the death rattle alone', false, 'Ruled out because this represents an inappropriate escalation of care for a symptom of the dying process itself; the focus at this stage is on comfort-focused symptom management, not intensive care transfer.', 4),
('f8000000-0000-0000-0000-000000000017', 'E', 'Consider an anticholinergic medication (e.g. hyoscine butylbromide or glycopyrronium) to reduce secretions, alongside repositioning and family reassurance', true, $x$Correct. Noisy respiratory secretions in the dying phase ('death rattle') can be managed with anticholinergic medication to reduce further secretion production (though existing secretions are not cleared by these drugs), alongside repositioning to aid drainage; importantly, family and carers should be reassured that this symptom, while often distressing to witness, does not typically indicate distress or suffering for the patient themselves, as they are usually not conscious of it at this stage.$x$, 5),
('f8000000-0000-0000-0000-000000000018', 'A', 'Complete bed rest and avoidance of all activity', false, 'Ruled out because complete inactivity can actually worsen deconditioning and fatigue over time; graded, tolerated activity/exercise has evidence for improving cancer-related fatigue, making complete rest an inappropriate blanket recommendation.', 1),
('f8000000-0000-0000-0000-000000000018', 'B', 'High-dose stimulant medication as the automatic first-line treatment for all patients', false, 'Ruled out because stimulant medications are not universally first-line or appropriate for all patients with cancer-related fatigue; a broader multimodal approach addressing modifiable factors and incorporating appropriate activity is the standard initial approach, with pharmacological options considered more selectively.', 2),
('f8000000-0000-0000-0000-000000000018', 'C', 'A multimodal approach including energy conservation strategies, graded exercise as tolerated, and addressing any remaining contributing factors, alongside honest discussion about realistic expectations', true, 'Correct. Cancer-related fatigue, once reversible contributing causes have been addressed, is managed with a multimodal approach including energy conservation strategies (prioritising activities, pacing), graded/tailored exercise as tolerated (which has evidence for improving fatigue in appropriately selected patients), and honest discussion about realistic expectations, given that fatigue in advanced cancer often cannot be fully resolved but can be better managed and its impact on quality of life reduced.', 3),
('f8000000-0000-0000-0000-000000000018', 'D', 'No management approach exists once reversible causes are excluded', false, 'Ruled out because a range of evidence-based, multimodal strategies exist to help manage cancer-related fatigue even when no single reversible cause is identified, contradicting this statement.', 4),
('f8000000-0000-0000-0000-000000000018', 'E', 'Reassurance alone with no active management strategies offered', false, 'Ruled out because active, multimodal management strategies (energy conservation, appropriate exercise, addressing contributing factors) provide meaningful benefit and should be offered, not simply reassurance without practical guidance.', 5),
('f8000000-0000-0000-0000-000000000019', 'A', 'High-dose insulin to stimulate appetite', false, 'Ruled out because insulin is not used as an appetite stimulant in this context and would be inappropriate and potentially dangerous (hypoglycaemia risk) without a specific diabetes-related indication.', 1),
('f8000000-0000-0000-0000-000000000019', 'B', 'Regular strong opioids specifically for appetite stimulation', false, 'Ruled out because opioids do not have an appetite-stimulating effect and are not used for this specific purpose; in fact, opioids can sometimes contribute to reduced appetite/nausea.', 2),
('f8000000-0000-0000-0000-000000000019', 'C', 'No pharmacological options exist to help with appetite in this context', false, 'Ruled out because corticosteroids (and, in some contexts, other specific agents such as progestogens for more sustained use, though these carry their own considerations) do have a recognised, evidence-based role in stimulating appetite in this population.', 3),
('f8000000-0000-0000-0000-000000000019', 'D', 'Corticosteroids (e.g. dexamethasone), used short-term given their appetite-stimulating effect', true, 'Correct. Corticosteroids have a recognised appetite-stimulating effect and are commonly used short-term in palliative care to help improve appetite and general wellbeing in patients with cancer-related anorexia, though this benefit is often time-limited (typically weeks) and must be balanced against the range of potential steroid side effects with longer-term use.', 4),
('f8000000-0000-0000-0000-000000000019', 'E', 'High-dose vitamin supplementation as the primary appetite stimulant', false, 'Ruled out because vitamin supplementation does not have an established, specific appetite-stimulating effect in this context in the way corticosteroids do.', 5),
('f8000000-0000-0000-0000-000000000020', 'A', 'No further intervention is possible once fluid reaccumulates', false, 'Ruled out because specific interventions, such as an indwelling peritoneal catheter, are available and appropriate to consider for recurrent, symptomatic malignant ascites, directly contradicting this statement.', 1),
('f8000000-0000-0000-0000-000000000020', 'B', 'Consideration of an indwelling peritoneal catheter to allow intermittent drainage at home, reducing the need for repeated hospital-based paracentesis', true, 'Correct. For patients with recurrent, rapidly reaccumulating malignant ascites requiring frequent drainage, an indwelling peritoneal catheter can be placed to allow intermittent drainage at home (by the patient, carer, or community nursing team), improving quality of life by reducing the burden of repeated hospital attendances for paracentesis.', 2),
('f8000000-0000-0000-0000-000000000020', 'C', 'Immediate surgical removal of the peritoneum as the standard approach', false, 'Ruled out because this is a vastly disproportionate and non-standard intervention for managing recurrent malignant ascites; drainage-based approaches (repeated paracentesis or indwelling catheter) are the standard, appropriate management options.', 3),
('f8000000-0000-0000-0000-000000000020', 'D', 'Strict fluid restriction alone as the primary management strategy', false, 'Ruled out because malignant ascites results from peritoneal fluid production/impaired drainage related to the underlying malignancy, not primarily from excess fluid intake; fluid restriction alone would not effectively address symptomatic reaccumulation.', 4),
('f8000000-0000-0000-0000-000000000020', 'E', 'Diuretics as the definitive, standalone solution for all cases of malignant ascites', false, 'Ruled out because although diuretics may have some role in select cases (particularly those with a component of portal hypertension), they are generally less effective for malignant ascites compared with cirrhotic ascites, and drainage-based approaches remain the primary management strategy for symptomatic malignant ascites.', 5),
('f8000000-0000-0000-0000-000000000021', 'A', 'Consider treatments targeting the cholestatic mechanism (e.g. bile acid sequestrants such as cholestyramine, or other agents used for cholestatic pruritus), alongside general skin care measures', true, 'Correct. Pruritus specifically related to cholestasis (from bile salt accumulation) may respond to treatments targeting this mechanism, such as bile acid sequestrants (e.g. cholestyramine), or other specific agents sometimes used in this context, alongside general supportive skin care measures (emollients, avoiding overheating); standard antihistamines are often less effective for this specific type of itch, as it is not primarily histamine-mediated.', 1),
('f8000000-0000-0000-0000-000000000021', 'B', 'Standard oral antihistamines as the most effective first-line treatment', false, 'Ruled out because cholestatic pruritus is not primarily histamine-mediated, meaning standard antihistamines are often relatively ineffective for this specific type of itch, unlike their more established role in histamine-mediated pruritus (e.g. allergic causes).', 2),
('f8000000-0000-0000-0000-000000000021', 'C', 'No treatment options exist for this specific type of itch', false, 'Ruled out because specific treatments targeting the cholestatic mechanism do exist and can provide meaningful relief, contradicting this statement.', 3),
('f8000000-0000-0000-0000-000000000021', 'D', 'Topical corticosteroids as the definitive, most effective treatment', false, 'Ruled out because although topical corticosteroids may have some general role in skin care, they are not the specific, most effective treatment for cholestasis-related pruritus, which is better targeted by addressing the underlying bile salt mechanism.', 4),
('f8000000-0000-0000-0000-000000000021', 'E', 'Aggressive scratching should be actively encouraged to relieve symptoms', false, 'Ruled out because scratching can worsen skin integrity and potentially increase infection risk without effectively resolving the underlying pruritic mechanism; general skin care advice typically includes measures to minimise scratching-related skin damage.', 5),
('f8000000-0000-0000-0000-000000000022', 'A', 'Pharmacological treatment alone, with no psychological support considered', false, 'Ruled out because addressing the psychological and existential dimensions of anxiety through appropriate support (not just medication) is an important part of holistic management, not medication in isolation.', 1),
('f8000000-0000-0000-0000-000000000022', 'B', 'Psychological support alone, with no consideration of pharmacological options ever', false, 'Ruled out because pharmacological treatment can provide important additional benefit for significant anxiety, particularly when psychological measures alone are insufficient, and should be considered as part of a combined approach rather than excluded entirely.', 2),
('f8000000-0000-0000-0000-000000000022', 'C', 'A combination of psychological support (e.g. counselling, and involvement of psychology/chaplaincy as appropriate) alongside consideration of pharmacological treatment (e.g. a short-term benzodiazepine or, for more sustained treatment, an antidepressant) if needed', true, 'Correct. Anxiety in the context of serious illness is best managed with a combined approach, incorporating psychological and emotional support (counselling, exploring specific fears and concerns, and spiritual/existential support as relevant) alongside pharmacological treatment where appropriate (e.g. short-term benzodiazepines for acute, significant anxiety, or antidepressants for more sustained anxiety management), reflecting the holistic, multidimensional nature of anxiety in this context.', 3),
('f8000000-0000-0000-0000-000000000022', 'D', 'No specific management is needed, as anxiety is an inevitable, unaddressable part of serious illness', false, 'Ruled out because although some degree of anxiety in the context of serious illness is understandable, significant, distressing anxiety warrants active, holistic management using the approaches described, not being disregarded as unaddressable.', 4),
('f8000000-0000-0000-0000-000000000022', 'E', 'Immediate high-dose antipsychotic medication as the primary treatment for anxiety', false, 'Ruled out because antipsychotics are not the standard first-line pharmacological treatment for anxiety in this context; benzodiazepines (short-term) or antidepressants (longer-term) are more appropriate pharmacological options, alongside psychological support.', 5),
('f8000000-0000-0000-0000-000000000023', 'A', 'Antibiotics, as this is assumed to be a bacterial infection', false, 'Ruled out because oral candidiasis is a fungal, not bacterial, infection; antibiotics would be ineffective and inappropriate treatment, and could potentially worsen candidiasis by further disrupting normal oral flora.', 1),
('f8000000-0000-0000-0000-000000000023', 'B', 'No treatment is needed, as oral symptoms are not important in palliative care', false, 'Ruled out because oral symptoms significantly affect comfort, oral intake and overall quality of life, making their assessment and appropriate treatment an important part of holistic palliative symptom management, not something to be disregarded.', 2),
('f8000000-0000-0000-0000-000000000023', 'C', 'Strong opioid analgesia alone, without addressing the underlying cause', false, 'Ruled out because although analgesia may have some adjunctive role if pain is significant, treating the underlying fungal infection directly with antifungal therapy is the appropriate primary treatment, not opioids alone without addressing the cause.', 3),
('f8000000-0000-0000-0000-000000000023', 'D', 'Immediate dental extraction of all teeth', false, 'Ruled out because this is a vastly disproportionate response to oral candidiasis; targeted antifungal treatment is the appropriate, far less invasive management approach.', 4),
('f8000000-0000-0000-0000-000000000023', 'E', 'Topical or systemic antifungal treatment (e.g. nystatin suspension or fluconazole)', true, 'Correct. Oral candidiasis, causing pain and discomfort affecting oral intake and quality of life, is treated with antifungal therapy, either topical (e.g. nystatin suspension) or systemic (e.g. oral fluconazole, particularly for more extensive or refractory cases), alongside general good oral hygiene measures as part of comprehensive symptom management.', 5),
('f8000000-0000-0000-0000-000000000024', 'A', 'Simply accepting the sedation as an unavoidable, permanent consequence of opioid therapy', false, 'Ruled out because although some initial sedation is common when starting or increasing opioids (to which tolerance often develops within days), persistent sedation beyond this initial period warrants active assessment and management, not simply being accepted as unavoidable and permanent.', 1),
('f8000000-0000-0000-0000-000000000024', 'B', 'Consider opioid dose reduction (if pain control allows) or opioid switching (rotation) to an alternative opioid, alongside excluding other contributing causes of drowsiness', true, 'Correct. Persistent opioid-induced sedation, despite otherwise stable dosing, warrants consideration of dose reduction (if pain control would still be adequate) or switching to an alternative opioid (opioid rotation, which can sometimes improve the balance of analgesia to side effects due to differing individual patient response to different opioids), alongside excluding other potential contributing causes of drowsiness (e.g. other sedating medications, metabolic disturbance, disease progression).', 2),
('f8000000-0000-0000-0000-000000000024', 'C', 'Immediate complete discontinuation of all opioid therapy regardless of pain control', false, 'Ruled out because abruptly stopping opioids would risk uncontrolled pain and withdrawal; a more measured approach (dose adjustment or switching, guided by ongoing pain control) is appropriate rather than complete discontinuation without consideration of her pain needs.', 3),
('f8000000-0000-0000-0000-000000000024', 'D', 'Addition of a further sedating medication to manage the sedation', false, 'Ruled out because adding another sedating medication would likely worsen, not improve, the drowsiness; addressing the opioid regimen itself (or excluding other causes) is the more appropriate approach.', 4),
('f8000000-0000-0000-0000-000000000024', 'E', 'No management options exist for this side effect', false, 'Ruled out because specific management strategies (dose adjustment, opioid switching, addressing other contributing factors) are available and should be actively considered, contradicting this statement.', 5),
('f8000000-0000-0000-0000-000000000025', 'A', 'High-dose opioids specifically to treat hiccups', false, 'Ruled out because opioids do not have a specific established role in treating hiccups and are not the standard pharmacological approach for this symptom.', 1),
('f8000000-0000-0000-0000-000000000025', 'B', 'No pharmacological treatment options exist for persistent hiccups', false, 'Ruled out because specific medications (metoclopramide, chlorpromazine, and others in refractory cases) do have recognised roles in managing persistent hiccups, contradicting this statement.', 2),
('f8000000-0000-0000-0000-000000000025', 'C', 'Antibiotics, assuming an infective cause', false, 'Ruled out because there is no indication of an infective process here; hiccups in this context more commonly relate to gastric distension, diaphragmatic irritation, or other non-infective mechanisms, not requiring antibiotic treatment.', 3),
('f8000000-0000-0000-0000-000000000025', 'D', 'Metoclopramide or chlorpromazine', true, 'Correct. For persistent, distressing hiccups in palliative care, pharmacological options include metoclopramide (particularly useful if gastric distension is a contributing factor) or chlorpromazine (a centrally acting option with an established, though not fully understood, effect on hiccups), alongside identifying and, where possible, addressing any underlying contributing cause (e.g. gastric distension, diaphragmatic irritation).', 4),
('f8000000-0000-0000-0000-000000000025', 'E', 'Immediate surgical intervention on the diaphragm', false, 'Ruled out because this is a vastly disproportionate response to persistent hiccups; pharmacological treatment is the appropriate initial approach, with surgical options reserved for very specific, rare, refractory circumstances.', 5),
('f8000000-0000-0000-0000-000000000026', 'A', 'No management is possible or worthwhile for this symptom', false, 'Ruled out because effective supportive measures do exist and can meaningfully improve comfort for patients with xerostomia, contradicting this statement.', 1),
('f8000000-0000-0000-0000-000000000026', 'B', 'Fluid restriction to manage the dry mouth', false, 'Ruled out because fluid restriction would worsen, not improve, dry mouth; encouraging appropriate oral fluid intake (as tolerated) and using saliva substitutes are the appropriate approaches instead.', 2),
('f8000000-0000-0000-0000-000000000026', 'C', 'Immediate discontinuation of all opioid therapy regardless of pain control', false, $x$Ruled out because although medication review is relevant, abruptly stopping opioids without considering ongoing pain control needs would be inappropriate; a more balanced approach considering all contributing factors and the patient's overall symptom burden is needed.$x$, 3),
('f8000000-0000-0000-0000-000000000026', 'D', 'Regular mouth care including frequent sips of fluid, ice chips, saliva substitutes, and good oral hygiene, alongside reviewing contributing medications where possible', true, 'Correct. Xerostomia (dry mouth) in palliative care is managed with regular, proactive mouth care measures -- frequent small sips of fluid or ice chips, saliva substitutes/sprays, good oral hygiene, and lip care -- alongside reviewing potentially contributing medications (including opioids and other drugs with anticholinergic effects) where clinically appropriate, as part of comprehensive supportive symptom management.', 4),
('f8000000-0000-0000-0000-000000000026', 'E', 'Strong antibiotics as the primary treatment for dry mouth', false, 'Ruled out because xerostomia is not primarily an infective process requiring antibiotic treatment; supportive mouth care measures are the appropriate management approach.', 5),
('f8000000-0000-0000-0000-000000000027', 'A', 'Continuing all previous treatments and interventions completely unchanged, regardless of the change in prognosis', false, 'Ruled out because many treatments appropriate for active, curative-intent or disease-modifying care may no longer be appropriate or beneficial once a patient is recognised as dying; a considered review and adjustment of the care plan is needed, not automatic continuation of everything unchanged.', 1),
('f8000000-0000-0000-0000-000000000027', 'B', 'Immediate withdrawal of all forms of care and monitoring, including symptom management', false, 'Ruled out because although many interventions may appropriately be stopped, active symptom management and holistic care continue and often intensify in focus during this stage, not withdrawal of all care.', 2),
('f8000000-0000-0000-0000-000000000027', 'C', 'No specific change in approach is needed until the patient has actually died', false, 'Ruled out because proactively recognising and responding to the dying phase, with an appropriately adjusted care plan, is important for providing the best possible quality of care and support during this time, not waiting until after death to make any changes.', 3),
('f8000000-0000-0000-0000-000000000027', 'D', 'Transfer to intensive care for maximal life-prolonging intervention', false, 'Ruled out because this would be inconsistent with the recognised shift towards comfort-focused end-of-life care in a patient with advanced, incurable disease entering the dying phase, rather than pursuing further aggressive, life-prolonging intervention.', 4),
('f8000000-0000-0000-0000-000000000027', 'E', 'A shift towards comfort-focused, holistic end-of-life care, with review of ongoing treatments for their continued appropriateness and benefit', true, 'Correct. Once a patient is recognised as likely entering the last days of life, the appropriate approach involves shifting focus towards comfort, holistic symptom management, and support for the patient and family, with careful review of ongoing treatments (medications, monitoring, interventions) to ensure they remain appropriate and burden-appropriate given the change in goals of care, rather than continuing all previous treatments unchanged by default.', 5),
('f8000000-0000-0000-0000-000000000028', 'A', 'Continuing to attempt oral administration regardless of swallowing difficulty', false, 'Ruled out because attempting oral medication in a patient unable to swallow reliably risks aspiration and inadequate symptom control; converting to an appropriate alternative route is the correct approach.', 1),
('f8000000-0000-0000-0000-000000000028', 'B', 'Stopping all medications entirely, including those needed for symptom control', false, 'Ruled out because essential symptom-control medications should be continued via an appropriate alternative route, not stopped entirely, which would risk uncontrolled distressing symptoms at this important stage.', 2),
('f8000000-0000-0000-0000-000000000028', 'C', 'Convert essential symptom-control medications to an appropriate alternative route (e.g. subcutaneous, often via syringe driver), while stopping medications no longer providing relevant benefit', true, 'Correct. When oral administration is no longer reliable, essential symptom-control medications (analgesics, antiemetics, and others as needed) are converted to an alternative route, commonly subcutaneous (often delivered via a continuous subcutaneous infusion/syringe driver), while medications no longer providing relevant benefit at this stage (e.g. long-term preventive medications such as statins) are appropriately stopped, reflecting a focused, individualised approach to medication review at the end of life.', 3),
('f8000000-0000-0000-0000-000000000028', 'D', 'Continuing every single medication she was previously taking via an alternative route, regardless of ongoing relevance', false, 'Ruled out because medication review at this stage specifically involves stopping those no longer providing relevant benefit (e.g. long-term preventive medications), not converting every previous medication to an alternative route regardless of continued appropriateness.', 4),
('f8000000-0000-0000-0000-000000000028', 'E', 'Immediate insertion of a nasogastric tube for all medication administration', false, 'Ruled out because this is not the standard or most appropriate approach for medication administration in the last days of life; subcutaneous routes are generally preferred as a less invasive, more comfortable option for this purpose in this context.', 5),
('f8000000-0000-0000-0000-000000000029', 'A', $x$The family's wishes should override the advance decision, as they know the patient best$x$, false, $x$Ruled out because family members do not have the legal authority to override a patient's own valid, applicable advance decision, regardless of their own views or relationship to the patient; the advance decision reflects the patient's own autonomous choice.$x$, 1),
('f8000000-0000-0000-0000-000000000029', 'B', 'The valid, applicable advance decision should be respected, even though the family disagrees', true, $x$Correct. A valid and applicable advance decision, made by a patient with capacity, is legally binding and must be respected once the patient lacks capacity, even if family members disagree; family members cannot override a patient's own clearly expressed, valid prior wishes, though sensitive communication and support for the family in understanding and accepting this decision remains an important part of care.$x$, 2),
('f8000000-0000-0000-0000-000000000029', 'C', 'The advance decision should be disregarded simply because of family disagreement', false, $x$Ruled out because family disagreement alone is not grounds for disregarding a valid, applicable advance decision; specific concerns about validity or applicability would need to be genuinely assessed, but simple disagreement with the patient's expressed wishes is not sufficient reason to override it.$x$, 3),
('f8000000-0000-0000-0000-000000000029', 'D', 'A court order is always required before any advance decision can be acted upon', false, 'Ruled out because valid, clearly applicable advance decisions can and should be acted upon directly by the clinical team without routinely requiring court involvement; courts become involved only in cases of genuine uncertainty or dispute about validity/applicability that cannot be resolved through usual clinical and ethical processes.', 4),
('f8000000-0000-0000-0000-000000000029', 'E', 'The medical team should simply do whatever avoids conflict with the family, regardless of the advance decision', false, $x$Ruled out because the clinical and ethical obligation is to respect the patient's own valid, previously expressed wishes, not simply to avoid family conflict at the expense of overriding the patient's autonomous decision.$x$, 5),
('f8000000-0000-0000-0000-000000000030', 'A', 'A holistic, individualised assessment weighing the risks and burdens of different feeding approaches against her quality of life, comfort and previously expressed wishes, involving the multidisciplinary team and family', true, 'Correct. Decisions about feeding in advanced dementia with recurrent aspiration require individualised, holistic assessment, weighing the risks (aspiration, discomfort) and burdens of different approaches (continued oral feeding with modified consistency and careful feeding techniques versus alternative feeding methods such as a feeding tube) against her comfort, quality of life, and any previously expressed wishes or values, recognising that evidence generally does not show a clear survival or aspiration-prevention benefit from tube feeding in advanced dementia, making this a nuanced, patient-centred decision rather than a default choice.', 1),
('f8000000-0000-0000-0000-000000000030', 'B', 'Automatic insertion of a feeding tube in all cases of recurrent aspiration regardless of individual circumstances', false, 'Ruled out because evidence generally does not support a uniform benefit from tube feeding in advanced dementia with recurrent aspiration, and blanket application of this intervention without individualised assessment is not appropriate, given the significant evidence base questioning routine use of artificial feeding in this specific population.', 2),
('f8000000-0000-0000-0000-000000000030', 'C', 'Complete cessation of all oral intake immediately, with no further discussion', false, 'Ruled out because this represents an extreme, premature response without the necessary holistic, individualised assessment and discussion that should inform such a significant decision.', 3),
('f8000000-0000-0000-0000-000000000030', 'D', 'The decision should be made purely by the family without any clinical input', false, 'Ruled out because appropriate clinical assessment (including specialist input from speech and language therapy and the wider multidisciplinary team) alongside family involvement is needed for this decision, not family decision-making in isolation without professional guidance.', 4),
('f8000000-0000-0000-0000-000000000030', 'E', 'No specific consideration of her comfort or quality of life is relevant to this decision', false, 'Ruled out because comfort and quality of life are central, essential considerations in this type of decision, not something to be disregarded in favour of a purely mechanical or risk-avoidance approach.', 5),
('f8000000-0000-0000-0000-000000000031', 'A', 'Override his wishes and provide ventilatory support regardless, once he can no longer communicate, given the shortened life expectancy involved', false, 'Ruled out because this would violate his autonomous right to refuse treatment, a fundamental ethical and legal principle that applies even when refusal is expected to shorten life; his clearly expressed, informed wishes should be respected and acted upon.', 1),
('f8000000-0000-0000-0000-000000000031', 'B', 'This request cannot be legally respected under any circumstances', false, 'Ruled out because informed refusal of treatment, including life-sustaining treatment, by a patient with capacity is legally recognised and must be respected; this is a well-established principle in medical ethics and law.', 2),
('f8000000-0000-0000-0000-000000000031', 'C', 'This represents a request for assisted dying that cannot be granted', false, 'Ruled out because declining unwanted treatment (even life-sustaining treatment) is legally and ethically distinct from assisted dying/euthanasia; it reflects the right to refuse intervention, not a request for an active intervention to end life.', 3),
('f8000000-0000-0000-0000-000000000031', 'D', 'Respect his informed decision, documenting it clearly (e.g. as a formal advance decision) and providing ongoing support and symptom management as his condition progresses', true, 'Correct. A patient with capacity has the right to refuse specific treatment, even life-sustaining treatment, and even when this is expected to shorten life; his clearly expressed, informed wish should be respected, ideally documented formally (e.g. as an advance decision to refuse treatment, given it relates to a future situation when he may lack capacity or the ability to communicate), with ongoing holistic support and symptom management provided as his condition progresses, distinct from active euthanasia or assisted dying, as this represents his right to decline unwanted medical intervention.', 4),
('f8000000-0000-0000-0000-000000000031', 'E', 'No documentation or formal planning is needed; his verbal wish alone is sufficient with no further action required', false, 'Ruled out because formal documentation (e.g. via an advance decision to refuse treatment) is important to ensure his wishes are clearly recorded and can be properly acted upon later, particularly given this relates to a future point when he may be unable to communicate or may lack capacity.', 5),
('f8000000-0000-0000-0000-000000000032', 'A', 'A DNACPR decision means all other treatment and care will also be withdrawn', false, $x$Ruled out because a DNACPR decision relates specifically to the single intervention of CPR; it does not imply withdrawal of other appropriate treatments or holistic care, which continue to be provided as clinically indicated and consistent with the patient's overall goals of care.$x$, 1),
('f8000000-0000-0000-0000-000000000032', 'B', 'Patient or family consent is legally required before a DNACPR decision can be made', false, 'Ruled out because DNACPR is a clinical decision about a specific treatment (CPR) that a clinician is not obligated to offer if deemed clinically inappropriate/unlikely to succeed; while communication and explanation are essential and expected practice, formal consent (as opposed to being informed of and having the opportunity to discuss the decision) is not a legal requirement in the way it might be for agreeing to a treatment being offered.', 2),
('f8000000-0000-0000-0000-000000000032', 'C', 'DNACPR decisions should never be discussed with patients or families, to avoid distress', false, 'Ruled out because sensitive, honest communication about DNACPR decisions is considered essential good practice, not something to be avoided; while these conversations require skill and sensitivity, avoiding them entirely is not the appropriate approach and can itself cause harm or distress from a lack of understanding or unexpected discovery of the decision.', 3),
('f8000000-0000-0000-0000-000000000032', 'D', $x$A DNACPR decision is only valid if made by the most senior doctor involved in the patient's care, with no input from anyone else$x$, false, 'Ruled out because although appropriately senior clinical input and responsibility is important, this does not accurately describe the collaborative, communicative process (involving the wider team and, crucially, sensitive discussion with the patient/family) that characterises good DNACPR decision-making.', 4),
('f8000000-0000-0000-0000-000000000032', 'E', 'A DNACPR decision is a clinical judgement about the likely lack of benefit (and potential harm) of attempting CPR, which should be made with sensitive communication involving the patient (or family, if the patient lacks capacity) wherever possible', true, $x$Correct. A DNACPR decision reflects a clinical judgement that attempting CPR would be unlikely to be successful or would not be in the patient's overall best interests given their underlying condition and expected mode of death; this decision should involve sensitive, honest communication with the patient (where they have capacity) or with family/those close to the patient (where the patient lacks capacity), explaining the clinical reasoning, while recognising that CPR is a specific treatment that does not require patient consent to withhold if deemed clinically inappropriate, though good communication remains an essential and expected part of this process.$x$, 5),
('f8000000-0000-0000-0000-000000000033', 'A', 'Facilitate a structured advance care planning discussion, documenting her wishes (which may include a formal advance decision to refuse specific treatments, and/or broader statements of wishes and preferences)', true, $x$Correct. Advance care planning involves a structured, proactive discussion exploring and documenting a patient's wishes and preferences for future care while they retain capacity, which can include formal advance decisions to refuse specific treatments (legally binding for the specified circumstances) alongside broader statements of wishes and values (informative but not necessarily legally binding in the same way), helping guide care if she later loses capacity to make decisions herself.$x$, 1),
('f8000000-0000-0000-0000-000000000033', 'B', 'No documentation is possible or useful until the patient actually loses capacity', false, 'Ruled out because advance care planning is specifically most valuable and effective when undertaken proactively while a patient retains capacity, allowing their own wishes to genuinely guide future care, rather than waiting until capacity is already lost.', 2),
('f8000000-0000-0000-0000-000000000033', 'C', 'Her wishes cannot be documented in any way that would be relevant to future care', false, 'Ruled out because structured advance care planning documentation, including formal advance decisions, is specifically designed to be relevant and, where properly made, legally binding for guiding future care decisions.', 3),
('f8000000-0000-0000-0000-000000000033', 'D', 'This discussion should be avoided entirely, as it may cause distress', false, 'Ruled out because while these conversations require sensitivity, avoiding them entirely denies patients the opportunity to have their voice and wishes genuinely inform their future care; skilled, compassionate facilitation of these discussions is considered good practice, not something to be avoided.', 4),
('f8000000-0000-0000-0000-000000000033', 'E', $x$Only her family's wishes should be documented, not her own$x$, false, $x$Ruled out because advance care planning specifically centres on the patient's own wishes and preferences (while she retains capacity to express them), not those of family members, though family can be involved in and informed by these discussions.$x$, 5),
('f8000000-0000-0000-0000-000000000034', 'A', 'This indicates he is being neglected and requires forced feeding or artificial hydration', false, 'Ruled out because forcing feeding or artificial hydration in this context is not generally recommended, as it does not typically improve comfort and can sometimes cause additional burden (e.g. fluid overload, increased secretions) without corresponding benefit at this stage of the dying process.', 1),
('f8000000-0000-0000-0000-000000000034', 'B', 'Reduced or absent oral intake is a natural, expected part of the dying process at this stage, and is not generally believed to cause suffering or significantly hasten death when it occurs as part of this natural process', true, $x$Correct. As part of the natural dying process, appetite and thirst typically diminish, and reduced or absent oral intake at this stage is not generally believed to cause suffering (the body's needs have changed) or significantly hasten death, which is instead primarily driven by the underlying advanced illness itself; providing this explanation, along with reassurance and guidance on appropriate mouth care for comfort, can help alleviate family distress and misunderstanding about this common, natural aspect of dying.$x$, 2),
('f8000000-0000-0000-0000-000000000034', 'C', 'This means he must be transferred to hospital immediately for artificial nutrition and hydration', false, $x$Ruled out because this would be inconsistent with his and the family's expressed wish for home-based, comfort-focused care, and artificial nutrition/hydration is not generally indicated or beneficial in this natural end-of-life context.$x$, 3),
('f8000000-0000-0000-0000-000000000034', 'D', 'No explanation or reassurance should be offered to the family regarding this symptom', false, 'Ruled out because providing clear, compassionate explanation and reassurance about this common, often misunderstood aspect of the dying process is an important part of supporting the family through this experience.', 4),
('f8000000-0000-0000-0000-000000000034', 'E', 'This definitely indicates he is in severe pain requiring immediate opioid dose escalation', false, 'Ruled out because reduced oral intake at the end of life is not, by itself, a specific indicator of uncontrolled pain; while pain should always be separately and appropriately assessed and treated if present, this particular symptom should not automatically be interpreted as a sign of inadequate pain control requiring dose escalation.', 5),
('f8000000-0000-0000-0000-000000000035', 'A', 'Palliative sedation is simply another term for euthanasia', false, 'Ruled out because palliative sedation and euthanasia are ethically and legally distinct: palliative sedation aims to relieve symptoms through reduced consciousness (using proportionate sedation for symptom control), with death resulting from the underlying illness, whereas euthanasia involves a deliberate act with the primary intent of ending life.', 1),
('f8000000-0000-0000-0000-000000000035', 'B', 'The primary intent of palliative sedation is to hasten death for a patient who is suffering', false, 'Ruled out because this misrepresents the ethical basis and intent of palliative sedation, which is specifically symptom relief/comfort, not hastening death; this distinction in intent is ethically and legally significant.', 2),
('f8000000-0000-0000-0000-000000000035', 'C', 'Palliative sedation aims to relieve severe, refractory distress by reducing consciousness to a level that provides symptom relief, with the primary intent being comfort, not hastening death (reflecting the doctrine of double effect)', true, 'Correct. Palliative sedation, used for severe, refractory symptoms unresponsive to standard treatment in the last days of life, aims to relieve distress by reducing consciousness (using the lowest effective level of sedation for symptom control), with the primary, explicit intent being symptom relief and comfort, not hastening death; this reflects the doctrine of double effect, where an intervention with a legitimate primary intent (comfort) is ethically distinguished from an intervention with the primary intent of causing death, even though sedation may have some incidental effect on the timing of an already expected, imminent death from the underlying terminal illness.', 3),
('f8000000-0000-0000-0000-000000000035', 'D', 'Palliative sedation should be used routinely for all patients in their last days of life, regardless of symptom control', false, 'Ruled out because palliative sedation is specifically reserved for severe, refractory symptoms not responding to standard optimised treatment, not used routinely for all dying patients regardless of their symptom control status.', 4),
('f8000000-0000-0000-0000-000000000035', 'E', 'Palliative sedation requires no specific ethical consideration or discussion, as it is a purely routine clinical decision', false, 'Ruled out because given its significant nature, palliative sedation appropriately involves careful ethical consideration, multidisciplinary discussion, and sensitive communication with the patient (if possible) and family, not being treated as a purely routine, undiscussed decision.', 5),
('f8000000-0000-0000-0000-000000000036', 'A', 'Continue all previous medications completely unchanged, regardless of the change in prognosis and goals of care', false, 'Ruled out because continuing medications aimed at long-term risk reduction, when the patient has a very limited prognosis measured in days, provides no meaningful benefit and adds unnecessary burden; this is inconsistent with appropriate, individualised end-of-life prescribing review.', 1),
('f8000000-0000-0000-0000-000000000036', 'B', 'Increase the dose of all his preventive medications to maximise their effect', false, 'Ruled out because this is entirely inappropriate given his very limited prognosis; increasing doses of medications aimed at long-term risk reduction provides no relevant benefit at this stage and only adds burden.', 2),
('f8000000-0000-0000-0000-000000000036', 'C', 'Stop medications no longer providing relevant benefit at this stage (e.g. statins, bisphosphonates, and often antihypertensives), focusing the regimen on comfort and symptom control', true, 'Correct. As part of end-of-life medication review, long-term preventive medications aimed at reducing future risk (statins, bisphosphonates) or treating conditions where the original goals of treatment (e.g. long-term cardiovascular risk reduction) are no longer relevant given the very limited prognosis are typically stopped, reducing pill burden and potential side effects, with the medication regimen refocused specifically on comfort and symptom control appropriate to this stage.', 3),
('f8000000-0000-0000-0000-000000000036', 'D', 'Stop all medications, including those needed for symptom control', false, 'Ruled out because although long-term preventive medications are appropriately stopped, medications needed for symptom control and comfort should be continued (via an appropriate route), not stopped entirely.', 4),
('f8000000-0000-0000-0000-000000000036', 'E', 'No medication review is needed or appropriate at this stage of illness', false, 'Ruled out because proactive medication review, refocusing the regimen towards comfort, is a recognised and important part of good end-of-life care, not something to be omitted.', 5),
('f8000000-0000-0000-0000-000000000037', 'A', $x$Only one service should ever be involved in a patient's care, with all others excluded$x$, false, 'Ruled out because multiple services often appropriately contribute complementary expertise and support in complex palliative care; the solution to confusion is better coordination and communication, not artificially restricting involvement to a single service.', 1),
('f8000000-0000-0000-0000-000000000037', 'B', 'Clear coordination and communication between all involved services, with a defined point of contact and shared understanding of roles, to ensure integrated, consistent care', true, 'Correct. Effective end-of-life and palliative care often involves multiple services (specialist palliative care/hospice, oncology, primary care, community nursing); clear coordination and communication between these teams, with a defined point of contact for the patient and family and a shared understanding of respective roles, is essential to avoid confusion, duplication, or gaps in care, ensuring an integrated, consistent approach.', 2),
('f8000000-0000-0000-0000-000000000037', 'C', 'The family should independently coordinate between all the different services themselves without support', false, 'Ruled out because this places an inappropriate burden on the family; effective coordination should be actively facilitated by the involved clinical teams, not left for the family to manage entirely alone.', 3),
('f8000000-0000-0000-0000-000000000037', 'D', 'No coordination is necessary, as each service will manage its own aspects independently with no need for communication', false, 'Ruled out because a lack of coordination and communication between services is precisely what leads to the confusion and potential care gaps or duplication described in this scenario; active coordination is essential, not unnecessary.', 4),
('f8000000-0000-0000-0000-000000000037', 'E', 'The GP should be excluded from any involvement once specialist palliative care becomes involved', false, 'Ruled out because GPs often continue to play an important, ongoing role in coordinated palliative care alongside specialist services, particularly for patients being cared for at home; exclusion is not the appropriate approach.', 5),
('f8000000-0000-0000-0000-000000000038', 'A', 'Progressive reduction in consciousness, altered breathing pattern (e.g. Cheyne-Stokes breathing), mottled/cool peripheries, and reduced urine output', true, $x$Correct. As death approaches within hours to days, common physical signs include progressive reduction in consciousness/increasing drowsiness, altered breathing patterns (such as Cheyne-Stokes breathing, with cycles of deep and shallow breaths), mottled and cool peripheries (reflecting reduced peripheral circulation), and reduced urine output, together reflecting the body's declining physiological function as part of the natural dying process.$x$, 1),
('f8000000-0000-0000-0000-000000000038', 'B', 'Sudden improvement in appetite and increased physical activity', false, 'Ruled out because this describes improvement, not the expected decline seen as death approaches; while brief periods of apparent lucidity can occasionally occur, a sustained improvement in appetite and activity would not be a typical sign of imminent death.', 2),
('f8000000-0000-0000-0000-000000000038', 'C', 'Warm, well-perfused peripheries with a bounding pulse', false, 'Ruled out because this describes signs more consistent with good peripheral perfusion, the opposite of the cool, mottled peripheries typically seen as circulation declines in the dying phase.', 3),
('f8000000-0000-0000-0000-000000000038', 'D', 'Increasing urine output and improved renal function', false, $x$Ruled out because reduced (not increased) urine output is typically seen as the body's systems decline in the final hours to days of life, reflecting reduced renal perfusion as part of the overall physiological decline.$x$, 4),
('f8000000-0000-0000-0000-000000000038', 'E', 'Complete resolution of all previous symptoms with no further changes expected', false, 'Ruled out because this does not reflect the typical, recognised pattern of progressive physical decline seen in the final hours to days of life; ongoing changes and symptom management needs are expected during this phase, not complete resolution.', 5),
('f8000000-0000-0000-0000-000000000039', 'A', '60mg subcutaneous morphine over 24 hours (same dose, no conversion)', false, 'Ruled out because the subcutaneous route has greater bioavailability than oral, meaning giving the same numerical dose subcutaneously would result in a significantly higher effective dose than intended, risking overdose/toxicity.', 1),
('f8000000-0000-0000-0000-000000000039', 'B', '120mg subcutaneous morphine over 24 hours (doubling the oral dose)', false, 'Ruled out because this would represent a substantial overdose relative to the correct converted dose, given the standard conversion requires dividing (not multiplying) the oral dose when switching to the more bioavailable subcutaneous route.', 2),
('f8000000-0000-0000-0000-000000000039', 'C', '15mg subcutaneous morphine over 24 hours (quartering the oral dose)', false, 'Ruled out because this significantly underestimates the correct conversion, which uses a divide-by-2 ratio, not divide-by-4, risking inadequate pain control from underdosing.', 3),
('f8000000-0000-0000-0000-000000000039', 'D', 'No conversion is possible between oral and subcutaneous morphine', false, 'Ruled out because standard, well-established conversion ratios exist and are routinely used in clinical practice to safely switch between these routes.', 4),
('f8000000-0000-0000-0000-000000000039', 'E', '30mg subcutaneous morphine over 24 hours', true, 'Correct. The standard oral-to-subcutaneous morphine conversion ratio is approximately 2:1 (oral dose divided by 2), reflecting the increased bioavailability of the subcutaneous route compared with oral administration; 60mg oral morphine over 24 hours converts to approximately 30mg subcutaneous morphine over 24 hours, delivered via continuous subcutaneous infusion.', 5),
('f8000000-0000-0000-0000-000000000040', 'A', 'The patch provides immediate analgesia from the moment of application, requiring no overlap with prior medication', false, 'Ruled out because this is the opposite of the correct approach; fentanyl patches have a delayed onset, making appropriate overlap with prior analgesia essential to avoid inadequate pain control during the transition.', 1),
('f8000000-0000-0000-0000-000000000040', 'B', 'The prior oral morphine should be stopped abruptly at the exact moment the patch is applied', false, $x$Ruled out because this would risk a significant gap in effective analgesia during the patch's delayed onset period; overlap with the prior medication (or adequate breakthrough dosing) is needed during this transition.$x$, 2),
('f8000000-0000-0000-0000-000000000040', 'C', 'No specific timing considerations are relevant when switching between these two opioid formulations', false, 'Ruled out because the specific pharmacokinetic profile of transdermal fentanyl (delayed onset) makes careful timing and overlap planning an important, specific consideration for this particular route switch.', 3),
('f8000000-0000-0000-0000-000000000040', 'D', 'Continue adequate analgesia (e.g. the prior modified-release morphine or equivalent breakthrough doses) for the first 12-24 hours after applying the patch, given its delayed onset of action', true, 'Correct. Because transdermal fentanyl patches take approximately 12-24 hours to reach therapeutic plasma concentrations after application, adequate analgesic cover (typically continuing the previous regular modified-release opioid for a period, or ensuring adequate breakthrough medication is available) must be maintained during this transition period to avoid a gap in pain control while the patch reaches its full effect.', 4),
('f8000000-0000-0000-0000-000000000040', 'E', 'The fentanyl patch dose should be doubled immediately if pain is not controlled within the first hour', false, 'Ruled out because patch effects take considerably longer than one hour to develop; a dose increase should not be made this rapidly, and any inadequate pain control during the expected onset period should be managed with appropriate breakthrough medication rather than premature patch dose escalation.', 5),
('f8000000-0000-0000-0000-000000000041', 'A', 'Exactly the same as the total 24-hour background dose, given as a single additional dose', false, 'Ruled out because this would represent a very large, potentially dangerous additional dose; the standard, much smaller one-sixth calculation is the appropriate approach for breakthrough dosing.', 1),
('f8000000-0000-0000-0000-000000000041', 'B', $x$A fixed dose of 5mg oral morphine regardless of the patient's background opioid requirement$x$, false, $x$Ruled out because breakthrough doses should be individually calculated based on the patient's specific total daily background dose, not applied as a fixed, one-size-fits-all amount regardless of their established opioid requirements.$x$, 2),
('f8000000-0000-0000-0000-000000000041', 'C', 'Half of the total 24-hour background dose', false, 'Ruled out because this significantly overestimates the standard, appropriate breakthrough dose calculation, which uses a one-sixth (not one-half) proportion of the total daily background dose.', 3),
('f8000000-0000-0000-0000-000000000041', 'D', 'Approximately one-sixth of the total 24-hour background opioid dose', true, 'Correct. The standard approach to calculating a breakthrough dose is approximately one-sixth of the total 24-hour background opioid dose, given as an immediate-release formulation, available for use as needed for episodes of breakthrough pain, with the total daily breakthrough dose used informing whether the background dose itself may need upward titration.', 4),
('f8000000-0000-0000-0000-000000000041', 'E', 'No specific calculation method exists; breakthrough doses are chosen entirely arbitrarily', false, 'Ruled out because a well-established, standard calculation method (approximately one-sixth of the total daily dose) exists and is routinely used in clinical practice for this purpose.', 5),
('f8000000-0000-0000-0000-000000000042', 'A', 'Any medications can be safely mixed together in a syringe driver without any specific compatibility checking', false, 'Ruled out because this is incorrect and potentially unsafe; not all medications are compatible when combined, and specific compatibility checking against reference guidance is an essential step before combining drugs in a syringe.', 1),
('f8000000-0000-0000-0000-000000000042', 'B', 'Syringe drivers can only ever contain a single medication, with no combinations ever used', false, 'Ruled out because combining multiple compatible medications in a single syringe driver is standard, common practice in palliative care, provided appropriate compatibility has been confirmed, not a practice that is never used.', 2),
('f8000000-0000-0000-0000-000000000042', 'C', 'Compatibility checking is only relevant for oral medications, not subcutaneous infusions', false, 'Ruled out because compatibility checking is specifically important and relevant for medications combined within a subcutaneous syringe driver, given the potential for physical or chemical interactions when mixed together in solution.', 3),
('f8000000-0000-0000-0000-000000000042', 'D', 'Only the total volume of the syringe needs to be considered, with no attention to which specific drugs are combined', false, 'Ruled out because although appropriate total volume/dilution is also a practical consideration, the compatibility of the specific drug combination itself is the primary and essential safety consideration, not simply volume.', 4),
('f8000000-0000-0000-0000-000000000042', 'E', 'Ensuring the combined medications are physically and chemically compatible when mixed together in the same syringe, using reference guidance where needed', true, 'Correct. When combining multiple medications in a single syringe driver, it is essential to check physical (e.g. no visible precipitation or discolouration) and chemical compatibility of the specific combination, using established compatibility reference guidance (such as local or national palliative care compatibility charts), as not all medications are compatible when mixed together, and incompatibility can affect drug stability/efficacy or cause visible/physical problems within the syringe.', 5),
('f8000000-0000-0000-0000-000000000043', 'A', 'Calculate the equianalgesic dose of the new opioid using standard conversion ratios, then consider a dose reduction (e.g. by around 25-50%) to account for incomplete cross-tolerance between different opioids', true, 'Correct. When switching between different opioids (opioid rotation), the equianalgesic dose of the new opioid is first calculated using standard conversion ratios, but this calculated dose is often then reduced (commonly by around 25-50%, depending on the specific opioids involved and clinical context) to account for incomplete cross-tolerance -- individual patients do not have full cross-tolerance between different opioids, meaning the calculated equianalgesic dose of a new opioid can sometimes have a stronger effect than expected, risking toxicity if not appropriately adjusted.', 1),
('f8000000-0000-0000-0000-000000000043', 'B', 'Simply give the full calculated equianalgesic dose without any adjustment', false, 'Ruled out because failing to account for incomplete cross-tolerance risks toxicity from the new opioid, even when using an accurately calculated equianalgesic dose; a degree of dose reduction is standard practice for safety.', 2),
('f8000000-0000-0000-0000-000000000043', 'C', 'Double the calculated equianalgesic dose to ensure adequate effect', false, 'Ruled out because this would significantly increase toxicity risk; the standard practice is dose reduction (not increase) to account for incomplete cross-tolerance when switching opioids.', 3),
('f8000000-0000-0000-0000-000000000043', 'D', 'No calculation or dose adjustment is needed; simply start the new opioid at an arbitrary standard starting dose regardless of the previous opioid dose', false, $x$Ruled out because this fails to account for the patient's established, significant opioid requirement, risking either inadequate analgesia (if the arbitrary dose is too low) or unsafe dosing without proper calculation.$x$, 4),
('f8000000-0000-0000-0000-000000000043', 'E', 'Opioid rotation is never appropriate or performed in clinical practice', false, 'Ruled out because opioid rotation is a well-established, recognised technique used specifically to improve the balance of analgesia to side effects when problems occur with a particular opioid, contradicting this statement.', 5),
('f8000000-0000-0000-0000-000000000044', 'A', '30mg immediate-release oral morphine', false, 'Ruled out because this equals the individual background dose amount, not the correctly calculated one-sixth of the total 24-hour dose (60mg), significantly overestimating the appropriate breakthrough dose.', 1),
('f8000000-0000-0000-0000-000000000044', 'B', '10mg immediate-release oral morphine', true, 'Correct. Total 24-hour background dose = 30mg twice daily = 60mg/24 hours; one-sixth of 60mg is 10mg, giving an appropriate breakthrough dose of 10mg immediate-release oral morphine, available as needed alongside the regular twice-daily modified-release background dosing.', 2),
('f8000000-0000-0000-0000-000000000044', 'C', '60mg immediate-release oral morphine', false, 'Ruled out because this equals the entire 24-hour background dose given as a single breakthrough dose, a substantial overestimate compared with the correctly calculated one-sixth proportion.', 3),
('f8000000-0000-0000-0000-000000000044', 'D', '5mg immediate-release oral morphine', false, 'Ruled out because this underestimates the correct calculation; one-sixth of the total 60mg/24 hour dose is 10mg, not 5mg.', 4),
('f8000000-0000-0000-0000-000000000044', 'E', 'No breakthrough medication should be prescribed alongside regular modified-release background dosing', false, 'Ruled out because breakthrough medication should routinely be prescribed alongside regular background opioid therapy, to manage any breakthrough pain episodes that occur between regular doses.', 5),
('f8000000-0000-0000-0000-000000000045', 'A', 'Never adjust the syringe driver dose regardless of breakthrough medication use', false, 'Ruled out because frequent breakthrough dose requirement is a clear indicator that the background dose likely needs upward adjustment; failing to review and adjust would leave the patient with ongoing inadequately controlled pain.', 1),
('f8000000-0000-0000-0000-000000000045', 'B', $x$Simply increase the breakthrough dose without any change to the syringe driver's background rate$x$, false, 'Ruled out because if background pain control is genuinely inadequate (reflected by frequent breakthrough need), the underlying background/syringe driver dose itself should be reviewed and typically increased, not just the breakthrough dose in isolation.', 2),
('f8000000-0000-0000-0000-000000000045', 'C', 'Recalculate the total 24-hour syringe driver dose based on the background requirement plus the additional breakthrough doses used, then adjust the breakthrough dose accordingly for the new total', true, $x$Correct. When breakthrough opioid use indicates inadequate background control, the syringe driver's 24-hour dose is typically increased to reflect the total opioid requirement (background plus breakthrough used), with the breakthrough dose itself then recalculated (again using the one-sixth principle) based on this new, higher total daily dose, ensuring the ongoing regimen appropriately reflects the patient's actual opioid requirement.$x$, 3),
('f8000000-0000-0000-0000-000000000045', 'D', 'Stop the syringe driver entirely and switch to oral medication only, regardless of the reason it was started', false, 'Ruled out because this does not address the core issue (inadequate dose) and may not be appropriate if the syringe driver was specifically needed due to inability to take oral medication; the priority is appropriately adjusting the current regimen.', 4),
('f8000000-0000-0000-0000-000000000045', 'E', 'Double the total syringe driver volume without recalculating the actual drug dose', false, 'Ruled out because simply increasing volume without correctly recalculating the actual drug dose would not appropriately or safely address the underlying inadequate analgesia; a proper dose recalculation is needed, not just a volume change.', 5),
('f8000000-0000-0000-0000-000000000046', 'A', 'A 1:1 ratio, with no dose adjustment needed between routes', false, 'Ruled out because oral and subcutaneous bioavailability differ, meaning a direct 1:1 conversion would not accurately reflect the equivalent dose between these two routes.', 1),
('f8000000-0000-0000-0000-000000000046', 'B', 'A 10:1 ratio, requiring a much lower subcutaneous dose', false, 'Ruled out because this significantly overestimates the actual bioavailability difference for oxycodone between these routes, which is approximately 2:1, not 10:1.', 2),
('f8000000-0000-0000-0000-000000000046', 'C', 'The subcutaneous route requires a higher numerical dose than the oral route', false, 'Ruled out because this is the opposite of the correct relationship; the subcutaneous route has greater bioavailability, meaning a lower (not higher) numerical dose is needed to achieve an equivalent effect compared with oral dosing.', 3),
('f8000000-0000-0000-0000-000000000046', 'D', 'No standard conversion ratio exists for oxycodone between these routes', false, 'Ruled out because standard, established conversion ratios do exist for oxycodone (as for other commonly used opioids) and are used in routine clinical practice.', 4),
('f8000000-0000-0000-0000-000000000046', 'E', 'Approximately 2:1 (oral dose divided by 2), similar in principle to the morphine oral-to-subcutaneous conversion', true, 'Correct. The oral-to-subcutaneous conversion ratio for oxycodone is approximately 2:1, similar in principle to morphine, reflecting comparable relative bioavailability differences between the oral and subcutaneous routes for this opioid; as with all opioid conversions, using accurate, current reference guidance (such as local formulary or specialist palliative care resources) is recommended given that specific ratios can vary slightly between different reference sources and clinical contexts.', 5),
('f8000000-0000-0000-0000-000000000047', 'A', 'Standard-dose morphine remains equally suitable regardless of renal function', false, $x$Ruled out because morphine's active metabolites accumulate in significant renal impairment, increasing toxicity risk; alternative opioids with more favourable properties in this context, such as alfentanil, are often preferred.$x$, 1),
('f8000000-0000-0000-0000-000000000047', 'B', 'Codeine is the preferred choice in significant renal impairment', false, 'Ruled out because codeine is a weak opioid with its own metabolite-related considerations, and is not the standard choice for managing moderate-to-severe pain requiring a strong opioid switch in significant renal impairment.', 2),
('f8000000-0000-0000-0000-000000000047', 'C', 'Alfentanil, given its metabolism produces less clinically significant active/accumulating metabolites dependent on renal clearance', true, 'Correct. Alfentanil is commonly considered in significant renal impairment (particularly via syringe driver in the last days of life) as its metabolism does not produce clinically significant active metabolites requiring renal clearance in the way morphine does, reducing the accumulation and toxicity risk seen with standard morphine dosing in this context; specialist palliative care input is often valuable given the complexity of opioid selection and dosing in significant renal impairment.', 3),
('f8000000-0000-0000-0000-000000000047', 'D', 'No opioid can be safely used in significant renal impairment', false, 'Ruled out because appropriately selected opioids, such as alfentanil, along with careful dosing and monitoring, can be used safely and effectively for pain control even in significant renal impairment.', 4),
('f8000000-0000-0000-0000-000000000047', 'E', 'The choice of opioid makes no difference in renal impairment, as all opioids behave identically', false, 'Ruled out because different opioids have different metabolic pathways and dependence on renal clearance for their active metabolites, meaning opioid choice is a genuinely important consideration in this context, not one where all options are equivalent.', 5),
('f8000000-0000-0000-0000-000000000048', 'A', 'Continue using the same site indefinitely despite the reaction, as this is a normal expected finding', false, 'Ruled out because a red, swollen, painful site is not a normal, inconsequential finding; it indicates local irritation likely affecting both comfort and potentially drug absorption, warranting resiting.', 1),
('f8000000-0000-0000-0000-000000000048', 'B', 'Resite the subcutaneous cannula to a new location, assessing whether the reaction is related to a specific drug or simply the site itself', true, 'Correct. A red, swollen, painful subcutaneous infusion site indicates local irritation, requiring the cannula to be resited to a new location to maintain effective drug absorption and patient comfort; the team should also consider whether a specific medication combination or concentration might be contributing to site reactions, which may inform site rotation frequency or medication adjustments going forward.', 2),
('f8000000-0000-0000-0000-000000000048', 'C', $x$Stop all subcutaneous medications permanently and switch to oral route regardless of the patient's ability to swallow$x$, false, 'Ruled out because this is a disproportionate response to a local site reaction; simply resiting the cannula is the appropriate immediate action, not abandoning the subcutaneous route entirely, particularly if the patient cannot reliably take oral medication.', 3),
('f8000000-0000-0000-0000-000000000048', 'D', 'Increase the infusion rate to compensate for reduced absorption at the irritated site', false, 'Ruled out because this does not address the underlying site problem and could risk inconsistent or excessive drug delivery once the site is functioning normally again (or once resited); addressing the site itself through resiting is the appropriate action.', 4),
('f8000000-0000-0000-0000-000000000048', 'E', 'No action is needed, as site reactions never affect drug delivery or comfort', false, 'Ruled out because site reactions can genuinely affect both patient comfort and potentially the reliability of drug absorption, making this an inaccurate statement and resiting the appropriate response.', 5),
('f8000000-0000-0000-0000-000000000049', 'A', 'Fentanyl absorption stops immediately upon patch removal, requiring no special timing consideration', false, 'Ruled out because this is incorrect; the depot effect means absorption continues for many hours after removal, making careful timing consideration essential when switching to a new opioid route.', 1),
('f8000000-0000-0000-0000-000000000049', 'B', 'The new syringe driver should be started at a significantly higher dose than usual to compensate for anticipated reduced fentanyl absorption', false, 'Ruled out because this would risk toxicity from the combined effect of continued fentanyl absorption plus a higher-than-usual new opioid dose; careful, cautious timing and dosing (not compensatory dose increases) is the appropriate approach.', 2),
('f8000000-0000-0000-0000-000000000049', 'C', 'No specific timing considerations apply when switching from a fentanyl patch to any other opioid formulation', false, 'Ruled out because the specific pharmacokinetic properties of transdermal fentanyl (delayed offset) do require particular attention when switching to a different opioid/route, unlike this statement suggests.', 3),
('f8000000-0000-0000-0000-000000000049', 'D', 'Fentanyl continues to be absorbed from the skin depot for a number of hours after patch removal, so the new syringe driver should typically be started with this delayed offset in mind, avoiding excessive overlap that could cause toxicity', true, $x$Correct. Due to the fentanyl patch's depot effect in the skin, drug continues to be absorbed and released into the circulation for approximately 12-24 hours after patch removal; when switching to a new opioid via syringe driver, this delayed offset must be considered to avoid excessive overlap and resulting toxicity, typically by starting the new infusion at a reduced rate initially or with appropriate timing guidance from specialist palliative care resources.$x$, 4),
('f8000000-0000-0000-0000-000000000049', 'E', 'The patch should be left in place indefinitely alongside the new syringe driver, with no removal', false, 'Ruled out because this would risk significant opioid toxicity from combining ongoing fentanyl absorption with the new syringe driver medication without appropriate limits on this overlap.', 5),
('f8000000-0000-0000-0000-000000000050', 'A', 'Assess for opioid toxicity, and if confirmed, reduce or temporarily stop the infusion, alongside considering other potential contributing causes of drowsiness', true, 'Correct. Increasing drowsiness with slow, shallow breathing in a patient on a continuous opioid infusion should prompt urgent assessment for opioid toxicity; if toxicity is confirmed (or strongly suspected), the infusion should be reduced or temporarily stopped, with close monitoring, while also considering and assessing for other potential contributing causes (e.g. renal function decline, other sedating medications, disease progression) that might be affecting opioid clearance or contributing to the presentation.', 1),
('f8000000-0000-0000-0000-000000000050', 'B', 'Immediately increase the syringe driver rate, assuming inadequate pain control is the cause', false, 'Ruled out because increasing the dose in the context of these specific signs (drowsiness, slow shallow breathing) would risk worsening toxicity; these signs specifically suggest excessive opioid effect requiring dose reduction, not evidence of inadequate pain control requiring escalation.', 2),
('f8000000-0000-0000-0000-000000000050', 'C', 'No assessment or action is needed, as drowsiness is always expected and requires no response', false, 'Ruled out because although some baseline sedation can occur with opioids, the combination of increasing drowsiness with respiratory depression (slow, shallow breathing) is a concerning sign of possible toxicity requiring active assessment and response, not something to be disregarded.', 3),
('f8000000-0000-0000-0000-000000000050', 'D', 'Stop all medications in the syringe driver permanently, including non-opioid components, without any specific reassessment', false, 'Ruled out because a more targeted, careful assessment and response (specifically addressing the opioid component if toxicity is confirmed) is more appropriate than an unreviewed, blanket permanent cessation of all syringe driver medications.', 4),
('f8000000-0000-0000-0000-000000000050', 'E', 'Administer high-dose caffeine to counteract the drowsiness', false, 'Ruled out because this is not an appropriate or evidence-based response to suspected opioid toxicity; the correct approach is assessing for and addressing the toxicity itself (dose reduction/temporary cessation), not attempting to counteract sedation with a stimulant.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('f8000000-0000-0000-0000-000000000001', 'The WHO analgesic ladder provides a structured, stepwise approach: non-opioid (step 1), weak opioid plus non-opioid (step 2), strong opioid plus non-opioid (step 3), escalating as needed based on pain severity and response.', 1),
('f8000000-0000-0000-0000-000000000001', 'Non-opioid analgesia (e.g. paracetamol) is typically continued alongside opioids at each subsequent step, rather than being stopped, as it can provide additive analgesic benefit.', 2),
('f8000000-0000-0000-0000-000000000001', 'This stepwise approach helps ensure proportionate, effective pain management, avoiding both under-treatment and unnecessarily rapid escalation to strong opioids.', 3),
('f8000000-0000-0000-0000-000000000002', 'Weak opioids (codeine, tramadol) have a ceiling effect, meaning further dose increases beyond a certain point provide little additional analgesic benefit while increasing side-effect burden, distinguishing them from strong opioids like morphine, which can generally be titrated to effect.', 1),
('f8000000-0000-0000-0000-000000000002', 'Continuing the non-opioid (paracetamol) alongside the newly started strong opioid reflects the WHO ladder principle of building on, rather than simply replacing, prior analgesic steps.', 2),
('f8000000-0000-0000-0000-000000000002', 'Careful titration of the strong opioid dose, guided by pain response and side effects, is essential for effective, safe pain control at this stage.', 3),
('f8000000-0000-0000-0000-000000000003', 'Neuropathic pain (burning quality, allodynia, radiating distribution) often responds only partially to opioids alone, distinguishing its management approach from purely nociceptive pain.', 1),
('f8000000-0000-0000-0000-000000000003', 'Adjuvant analgesics (gabapentinoids, tricyclic antidepressants) target neuropathic pain mechanisms specifically, providing benefit that opioid dose escalation alone may not achieve.', 2),
('f8000000-0000-0000-0000-000000000003', 'Recognising a significant neuropathic pain component is important for appropriately tailoring the overall analgesic regimen, often combining opioid and adjuvant treatment for optimal control.', 3),
('f8000000-0000-0000-0000-000000000004', 'Breakthrough pain, distinct from background pain, requires a fast-acting analgesic formulation for prompt relief, complementing the slower-onset, longer-duration modified-release background medication.', 1),
('f8000000-0000-0000-0000-000000000004', 'The breakthrough dose is typically calculated as approximately one-sixth of the total daily background opioid dose, providing a standard, evidence-based starting point for prescribing.', 2),
('f8000000-0000-0000-0000-000000000004', 'Frequent need for breakthrough doses may indicate that the background dose itself requires upward titration, highlighting the importance of reviewing overall opioid requirements based on breakthrough use patterns.', 3),
('f8000000-0000-0000-0000-000000000005', $x$Morphine's active metabolites are renally excreted, meaning significant renal impairment increases the risk of accumulation and toxicity, distinct from a simple reduction in drug efficacy.$x$, 1),
('f8000000-0000-0000-0000-000000000005', 'Alternative opioid choices, or careful dose/interval adjustment with cautious monitoring, help balance effective analgesia against the accumulation risk in renal impairment.', 2),
('f8000000-0000-0000-0000-000000000005', 'Close monitoring for signs of opioid toxicity (increasing sedation, confusion, respiratory depression) is particularly important when prescribing opioids in the context of renal impairment, given the altered pharmacokinetics.', 3),
('f8000000-0000-0000-0000-000000000006', 'Unlike many other opioid side effects, tolerance to opioid-induced constipation does not typically develop over time, meaning ongoing, proactive laxative co-prescription is needed for the duration of opioid therapy.', 1),
('f8000000-0000-0000-0000-000000000006', 'A combination approach (typically a stimulant laxative plus a softener) is generally more effective than either class alone for opioid-induced constipation.', 2),
('f8000000-0000-0000-0000-000000000006', 'Prophylactic laxative prescription from the start of opioid therapy, rather than waiting for constipation to develop, is recommended best practice given the predictability of this side effect.', 3),
('f8000000-0000-0000-0000-000000000007', 'Opioid-induced hyperalgesia should be considered when pain worsens despite (or because of) opioid dose escalation, a paradoxical and clinically important phenomenon to recognise, as the appropriate response (reducing, not increasing, opioid dose) is counterintuitive.', 1),
('f8000000-0000-0000-0000-000000000007', 'Myoclonus is a recognised sign of opioid toxicity/accumulation, often accompanying hyperalgesia in this clinical picture, particularly relevant with high-dose or rapidly escalating therapy.', 2),
('f8000000-0000-0000-0000-000000000007', 'Management typically involves careful opioid dose reduction, switching to an alternative opioid (opioid rotation, which can improve the balance of analgesia to side effects), or incorporating adjuvant, non-opioid analgesic strategies, rather than continuing to escalate the causative opioid.', 3),
('f8000000-0000-0000-0000-000000000008', 'Localised radiotherapy provides site-specific pain relief for bone metastases, complementing systemic analgesia rather than replacing the need for overall pain management strategy.', 1),
('f8000000-0000-0000-0000-000000000008', 'Radiotherapy also reduces the risk of pathological fracture at the treated site, providing benefit beyond pain relief alone.', 2),
('f8000000-0000-0000-0000-000000000008', 'This combination approach (systemic analgesia plus targeted localised treatment) reflects the broader principle in palliative pain management of using multiple complementary modalities tailored to the specific pain mechanism and location.', 3),
('f8000000-0000-0000-0000-000000000009', 'Hepatic impairment can reduce the metabolism of many opioids, increasing the risk of accumulation and toxicity, similar in principle to the accumulation risk seen with renal impairment for certain opioids, though the specific pharmacokinetic considerations differ.', 1),
('f8000000-0000-0000-0000-000000000009', 'Lower starting doses with slower, more cautious titration allow safer opioid use in this context, balancing effective analgesia against the increased toxicity risk.', 2),
('f8000000-0000-0000-0000-000000000009', 'Given the complexity of prescribing in significant organ impairment, specialist palliative care or pharmacy input can be valuable in guiding the safest, most effective opioid choice and dosing strategy.', 3),
('f8000000-0000-0000-0000-000000000010', $x$The 'total pain' concept, originating from the hospice/palliative care movement, emphasises that effective pain management in serious illness requires attention to physical, psychological, social and spiritual dimensions together, not physical factors in isolation.$x$, 1),
('f8000000-0000-0000-0000-000000000010', 'Addressing psychological distress (anxiety, fear about prognosis) and social/existential concerns (worry about family) can meaningfully improve the overall experience of pain, alongside appropriate physical/pharmacological pain management.', 2),
('f8000000-0000-0000-0000-000000000010', 'This holistic framework underpins the multidisciplinary approach characteristic of palliative care, involving not just medical/pharmacological input but also psychological, social work, and chaplaincy/spiritual care support as relevant to the individual patient.', 3),
('f8000000-0000-0000-0000-000000000011', 'Coeliac plexus block specifically targets the visceral sympathetic pain pathway relevant to pancreatic and other upper abdominal cancers, reflecting a mechanism-targeted interventional approach distinct from systemic pharmacological management.', 1),
('f8000000-0000-0000-0000-000000000011', 'This technique can significantly reduce pain and systemic opioid requirements, potentially improving quality of life by reducing opioid-related side effects while maintaining effective pain control.', 2),
('f8000000-0000-0000-0000-000000000011', 'Interventional pain techniques like this represent an important component of the broader palliative pain management toolkit, used when appropriate alongside (not necessarily instead of) pharmacological approaches, particularly for specific, refractory pain syndromes.', 3),
('f8000000-0000-0000-0000-000000000012', 'The slow onset of transdermal fentanyl means adequate background analgesia (e.g. via overlap with the previous regular analgesic) must be ensured during the initial hours after first applying a patch, before it reaches full effect.', 1),
('f8000000-0000-0000-0000-000000000012', 'The slow offset (continued absorption from a skin depot after patch removal) is important to consider if switching away from fentanyl patches or managing suspected toxicity, as effects can persist for many hours after removal.', 2),
('f8000000-0000-0000-0000-000000000012', 'This pharmacokinetic profile makes transdermal fentanyl well suited to stable, established background pain control but unsuitable for rapid dose titration in unstable or rapidly changing pain, where oral or other faster-acting routes are preferred during the titration phase.', 3),
('f8000000-0000-0000-0000-000000000013', 'Starting with a relatively low dose in opioid-naive patients balances the need for effective analgesia against the risk of excessive sedation or other side effects during initial titration.', 1),
('f8000000-0000-0000-0000-000000000013', 'Using an immediate-release formulation initially allows more responsive dose adjustment and provides the basis for later breakthrough dose calculations once a stable regimen is established.', 2),
('f8000000-0000-0000-0000-000000000013', 'Regular review during the titration phase is essential to balance achieving adequate pain control against monitoring for and managing any emerging side effects.', 3),
('f8000000-0000-0000-0000-000000000014', 'Palliative care antiemetic selection is often guided by the most likely underlying mechanism (e.g. chemical/metabolic, gastric stasis, bowel obstruction, vestibular, raised intracranial pressure), rather than using a single default agent for all nausea.', 1),
('f8000000-0000-0000-0000-000000000014', $x$Haloperidol's action at the chemoreceptor trigger zone makes it particularly suited to nausea with a presumed chemical or metabolic driver, once causes like hypercalcaemia have been considered/excluded.$x$, 2),
('f8000000-0000-0000-0000-000000000014', 'This mechanism-based approach to antiemetic selection reflects a broader palliative care principle of tailoring symptom management to the most likely underlying cause, rather than empirical trial-and-error alone.', 3),
('f8000000-0000-0000-0000-000000000015', $x$Metoclopramide's prokinetic action makes it particularly suited to nausea from gastric stasis or partial/functional obstruction, but requires careful consideration in complete mechanical obstruction, where increased peristalsis against a fixed blockage could theoretically worsen colicky pain.$x$, 1),
('f8000000-0000-0000-0000-000000000015', 'Careful clinical (and sometimes radiological) assessment of whether an obstruction is complete or partial, and mechanical versus functional, helps guide the safest and most effective antiemetic choice in this context.', 2),
('f8000000-0000-0000-0000-000000000015', 'Malignant bowel obstruction management often requires a multidisciplinary approach, combining antiemetics, other symptom-focused medications (e.g. antisecretory agents), and consideration of whether surgical intervention is appropriate for the individual patient.', 3),
('f8000000-0000-0000-0000-000000000016', 'Low-dose opioids for breathlessness are used at doses generally lower than typical analgesic doses, reflecting their specific role in symptom palliation rather than pain control.', 1),
('f8000000-0000-0000-0000-000000000016', 'This approach is used alongside, not instead of, optimal treatment of any underlying reversible causes of breathlessness and non-pharmacological supportive measures.', 2),
('f8000000-0000-0000-0000-000000000016', 'The evidence for opioids in refractory breathlessness relates to their central effect on reducing the perceived sensation and distress of dyspnoea, a distinct mechanism from their analgesic action on pain pathways.', 3),
('f8000000-0000-0000-0000-000000000017', 'Anticholinergic medications reduce further secretion production but do not clear existing secretions already present, which is why earlier initiation (once the symptom is recognised) can be more effective than starting once secretions have already accumulated significantly.', 1),
('f8000000-0000-0000-0000-000000000017', 'Explaining to family and carers that this symptom typically does not reflect patient distress or suffering (as consciousness is usually significantly reduced at this stage) is an important, often underemphasised, part of managing the impact of this symptom on those present.', 2),
('f8000000-0000-0000-0000-000000000017', 'Repositioning (e.g. semi-prone or lateral position) can help with secretion drainage as a simple, non-pharmacological adjunct alongside medication.', 3),
('f8000000-0000-0000-0000-000000000018', 'Cancer-related fatigue is multifactorial, and even after addressing clearly reversible causes (anaemia, hypothyroidism, depression, medication effects), a residual component often remains requiring ongoing, multimodal management rather than a single definitive treatment.', 1),
('f8000000-0000-0000-0000-000000000018', 'Graded, individually tailored exercise has evidence for improving cancer-related fatigue, contrasting with the historical assumption that rest is always the appropriate response to fatigue in this context.', 2),
('f8000000-0000-0000-0000-000000000018', 'Setting realistic expectations, given that fatigue in advanced cancer often cannot be fully eliminated, is an important part of holistic symptom management, helping patients and families adapt while still maximising achievable quality of life.', 3),
('f8000000-0000-0000-0000-000000000019', $x$Corticosteroids' appetite-stimulating effect is well-recognised in palliative care, though typically most beneficial and appropriate for shorter-term use given the cumulative side-effect burden of longer-term steroid therapy.$x$, 1),
('f8000000-0000-0000-0000-000000000019', 'The underlying cause and reversibility of reduced appetite/cachexia should be considered, as cancer cachexia (a complex, multifactorial metabolic syndrome) may respond only partially to appetite stimulation alone, distinct from simple reduced oral intake from other causes.', 2),
('f8000000-0000-0000-0000-000000000019', 'Discussions about appetite and eating in advanced illness should also address the emotional and social significance of food, providing holistic support to patients and families alongside any pharmacological intervention.', 3),
('f8000000-0000-0000-0000-000000000020', 'An indwelling peritoneal catheter specifically addresses the burden of recurrent, frequent paracentesis by allowing more convenient, less hospital-dependent symptom management, improving overall quality of life for appropriately selected patients.', 1),
('f8000000-0000-0000-0000-000000000020', $x$This intervention reflects the broader palliative care principle of tailoring practical, quality-of-life-focused interventions to the specific pattern and burden of a patient's recurrent symptoms.$x$, 2),
('f8000000-0000-0000-0000-000000000020', $x$Decisions about indwelling catheter placement involve considering factors such as expected prognosis, infection risk, and the patient's and family's ability to manage drainage, guiding individualised decision-making.$x$, 3),
('f8000000-0000-0000-0000-000000000021', 'Recognising that cholestatic pruritus has a different underlying mechanism (bile salt accumulation, and other proposed mediators) from histamine-mediated itch is important for selecting genuinely effective, mechanism-targeted treatment rather than defaulting to standard antihistamines.', 1),
('f8000000-0000-0000-0000-000000000021', 'General skin care measures (emollients, avoiding factors that worsen dryness/irritation, avoiding overheating) provide supportive benefit alongside any specific pharmacological treatment for the underlying cause.', 2),
('f8000000-0000-0000-0000-000000000021', 'This mechanism-based approach to pruritus management mirrors the broader palliative care principle applied to other symptoms (like nausea), tailoring treatment to the most likely underlying cause rather than a uniform approach for all presentations of a given symptom.', 3),
('f8000000-0000-0000-0000-000000000022', 'Anxiety in serious illness often has genuine, understandable roots in specific fears and concerns (about symptoms, dying, family impact), making psychological exploration and support a core, not optional, component of management.', 1),
('f8000000-0000-0000-0000-000000000022', 'Pharmacological treatment choice depends on the anticipated duration and severity of anxiety, with short-term benzodiazepines useful for acute, severe anxiety and antidepressants better suited to more sustained anxiety management.', 2),
('f8000000-0000-0000-0000-000000000022', $x$This combined, holistic approach mirrors the broader 'total pain'/total symptom concept in palliative care, recognising the interconnection between psychological, physical and other dimensions of the patient's experience.$x$, 3),
('f8000000-0000-0000-0000-000000000023', 'Recognising oral candidiasis clinically (typically white plaques or erythematous changes on examination) allows targeted antifungal treatment rather than assuming a different (e.g. bacterial) cause.', 1),
('f8000000-0000-0000-0000-000000000023', $x$Choice between topical and systemic antifungal treatment depends on the extent and severity of infection, as well as the patient's ability to use topical preparations effectively.$x$, 2),
('f8000000-0000-0000-0000-000000000023', 'Good oral hygiene and regular mouth care are important supportive measures alongside specific antifungal treatment, reflecting the broader importance of oral symptom management in maintaining comfort and quality of life in palliative care.', 3),
('f8000000-0000-0000-0000-000000000024', 'While mild initial sedation is common and often improves with tolerance over the first few days of opioid therapy or after a dose increase, persistent sedation beyond this period should prompt active reassessment rather than being accepted indefinitely.', 1),
('f8000000-0000-0000-0000-000000000024', $x$Opioid switching (rotation) can sometimes improve the balance between analgesia and side effects, reflecting individual variation in response to different opioids even at pharmacologically 'equivalent' doses.$x$, 2),
('f8000000-0000-0000-0000-000000000024', 'A broader assessment excluding other potential contributors to drowsiness (other sedating medications, hypercalcaemia, renal/hepatic impairment, disease progression affecting cognition) is important before attributing persistent sedation solely to the opioid itself.', 3),
('f8000000-0000-0000-0000-000000000025', 'Identifying a potential underlying contributing cause (gastric distension, diaphragmatic or phrenic nerve irritation, central causes) can help guide the most appropriate specific treatment choice, though empirical treatment is also commonly used when a clear cause is not identified.', 1),
('f8000000-0000-0000-0000-000000000025', $x$Metoclopramide's prokinetic action makes it particularly useful when gastric distension is a likely contributing factor to hiccups.$x$, 2),
('f8000000-0000-0000-0000-000000000025', 'Persistent, distressing hiccups, though sometimes considered a minor symptom, can significantly affect sleep, oral intake, and overall quality of life, making active management an important part of holistic palliative symptom care.', 3),
('f8000000-0000-0000-0000-000000000026', 'Regular, proactive mouth care is a simple but important supportive measure that can significantly improve comfort in patients with xerostomia, a common symptom in advanced illness.', 1),
('f8000000-0000-0000-0000-000000000026', 'Multiple factors often contribute to xerostomia in this population (medications including opioids and anticholinergics, reduced oral intake, mouth breathing, and sometimes disease- or treatment-related factors), making a holistic assessment valuable.', 2),
('f8000000-0000-0000-0000-000000000026', 'Good oral care also has broader benefits beyond comfort, including reducing the risk of complications such as oral candidiasis, reinforcing its importance as a routine part of holistic palliative care.', 3),
('f8000000-0000-0000-0000-000000000027', 'Recognising when a patient is entering the last days of life is an important clinical skill, prompting a deliberate, proactive shift in the goals and focus of care towards comfort and holistic support.', 1),
('f8000000-0000-0000-0000-000000000027', 'Reviewing and adjusting ongoing treatments (stopping those no longer providing benefit or adding burden, while continuing/intensifying symptom-focused care) reflects individualised, patient-centred decision-making appropriate to this stage.', 2),
('f8000000-0000-0000-0000-000000000027', 'This shift in focus should be communicated sensitively and clearly with the patient (where possible) and family, supporting shared understanding and appropriate expectations during this significant transition in care.', 3),
('f8000000-0000-0000-0000-000000000028', 'Route conversion (commonly to subcutaneous administration) ensures continued effective symptom control when oral administration is no longer reliable, reflecting practical, patient-centred prescribing adapted to changing clinical circumstances.', 1),
('f8000000-0000-0000-0000-000000000028', 'Reviewing and stopping medications no longer providing relevant benefit (e.g. long-term preventive treatments) reduces unnecessary burden, focusing the remaining medication regimen on comfort and symptom control appropriate to this stage of care.', 2),
('f8000000-0000-0000-0000-000000000028', 'A syringe driver allows continuous subcutaneous delivery of multiple compatible medications together, providing steady symptom control without requiring repeated individual injections.', 3),
('f8000000-0000-0000-0000-000000000029', 'Advance decisions, once confirmed as valid (properly made, not subsequently withdrawn) and applicable to the current clinical situation, are legally binding, reflecting the fundamental principle of respecting patient autonomy even after capacity is lost.', 1),
('f8000000-0000-0000-0000-000000000029', $x$Family members, while important in providing information about a patient's wishes and values in the absence of an advance decision (as part of best interests decision-making), cannot legally override a patient's own valid, documented advance decision.$x$, 2),
('f8000000-0000-0000-0000-000000000029', $x$Sensitive, ongoing communication and support for family members who disagree with a patient's advance decision is an important part of holistic care, helping them understand and, ideally, come to accept the situation, even though the decision itself is not changed by their disagreement.$x$, 3),
('f8000000-0000-0000-0000-000000000030', 'Evidence generally does not demonstrate that tube feeding reduces aspiration risk or improves survival in advanced dementia, an important, sometimes counterintuitive, evidence base informing this type of decision.', 1),
('f8000000-0000-0000-0000-000000000030', $x$Individualised, holistic assessment -- weighing risks, burdens, comfort, and the patient's own previously expressed wishes or values -- is essential, rather than applying a uniform approach to all patients with this clinical picture.$x$, 2),
('f8000000-0000-0000-0000-000000000030', 'Multidisciplinary involvement (speech and language therapy, medical team, nursing, and family) supports well-rounded, informed decision-making that considers all relevant clinical and personal factors.', 3),
('f8000000-0000-0000-0000-000000000031', 'The right to refuse treatment, even life-sustaining treatment, is a fundamental principle for patients with capacity, distinct from requests for active intervention to end life (assisted dying/euthanasia).', 1),
('f8000000-0000-0000-0000-000000000031', 'Formal documentation of this type of decision (as an advance decision to refuse treatment) is important given it relates to a future clinical situation where the patient may lack capacity or the ability to communicate at the relevant time.', 2),
('f8000000-0000-0000-0000-000000000031', $x$Respecting this decision does not mean withdrawing all care; ongoing holistic support, symptom management and communication remain essential as the patient's condition progresses, reflecting comprehensive, patient-centred palliative care alongside respect for his treatment decision.$x$, 3),
('f8000000-0000-0000-0000-000000000032', 'A DNACPR decision specifically addresses the single intervention of CPR, based on clinical judgement about likely lack of benefit, and does not imply broader withdrawal of care or treatment.', 1),
('f8000000-0000-0000-0000-000000000032', 'While formal consent is not required to withhold a treatment judged clinically inappropriate, sensitive, proactive communication with the patient (or family, if the patient lacks capacity) about the decision and the reasoning behind it is considered essential good practice, not optional.', 2),
('f8000000-0000-0000-0000-000000000032', 'This distinction between clinical decision-making authority and the ethical/practical importance of communication reflects a nuanced balance in end-of-life care, avoiding both a purely paternalistic approach and an inappropriate expectation that families must consent to every specific clinical decision.', 3),
('f8000000-0000-0000-0000-000000000033', 'Advance care planning is most effective when undertaken proactively, while a patient retains capacity, allowing genuine exploration and documentation of their own wishes and values.', 1),
('f8000000-0000-0000-0000-000000000033', 'Formal advance decisions to refuse specific treatments carry legal weight for the specified future circumstances, distinct from broader, informative (but not necessarily legally binding in the same way) statements of general wishes and preferences.', 2),
('f8000000-0000-0000-0000-000000000033', 'Skilled, sensitive facilitation of these discussions, rather than avoidance, supports patients in having meaningful input into their future care, an important aspect of patient-centred palliative and end-of-life care.', 3),
('f8000000-0000-0000-0000-000000000034', $x$Understanding that reduced oral intake is a natural, expected physiological change in the dying process (rather than a cause of suffering or a sign of neglect) is important both for appropriate clinical management and for supporting families' understanding and emotional adjustment.$x$, 1),
('f8000000-0000-0000-0000-000000000034', 'Good mouth care (as discussed for xerostomia) remains important for comfort even when oral intake has stopped, addressing dryness and discomfort without requiring nutritional intake.', 2),
('f8000000-0000-0000-0000-000000000034', 'Clear, compassionate communication with families about normal aspects of the dying process is a core skill in end-of-life care, helping reduce distress arising from common misunderstandings about symptoms at this stage.', 3),
('f8000000-0000-0000-0000-000000000035', 'The doctrine of double effect is a key ethical principle underlying palliative sedation, distinguishing an intervention with a legitimate primary intent (symptom relief) from one with the intent to cause death, even when both might involve some similar practical elements (e.g. use of sedating medication).', 1),
('f8000000-0000-0000-0000-000000000035', 'Palliative sedation is specifically reserved for severe, refractory symptoms that have not responded to standard, optimised palliative treatment approaches, reflecting its role as an option for exceptional circumstances rather than routine practice.', 2),
('f8000000-0000-0000-0000-000000000035', 'Using the lowest effective level of sedation needed to achieve symptom relief (rather than deep, complete sedation as a default) reflects the proportionate, symptom-focused intent underlying this approach, distinguishing it from a deliberate act intended to end life.', 3),
('f8000000-0000-0000-0000-000000000036', 'Medications aimed at reducing long-term risk (statins, bisphosphonates, and often antihypertensives, depending on individual symptoms) generally provide no meaningful benefit within a prognosis of days, making their continuation inappropriate at this stage.', 1),
('f8000000-0000-0000-0000-000000000036', $x$This review reduces unnecessary pill burden, potential side effects, and the practical difficulty of medication administration, refocusing the regimen on what genuinely benefits the patient's comfort in their remaining time.$x$, 2),
('f8000000-0000-0000-0000-000000000036', 'This principle mirrors the broader deprescribing approach used in patients with significantly limited life expectancy or advanced frailty, reflecting a consistent, evidence-based approach to prescribing across different clinical contexts nearing the end of life.', 3),
('f8000000-0000-0000-0000-000000000037', 'Multiple services often appropriately contribute to complex palliative and end-of-life care, reflecting the range of needs (specialist symptom management, ongoing primary care, community nursing support) that can arise.', 1),
('f8000000-0000-0000-0000-000000000037', 'Clear communication channels and a defined point of contact help ensure the patient and family have clarity about who to approach for different needs, reducing confusion and supporting continuity of care.', 2),
('f8000000-0000-0000-0000-000000000037', 'Good coordination between services is a recognised marker of high-quality palliative care, directly impacting patient and family experience and confidence in the care being provided.', 3),
('f8000000-0000-0000-0000-000000000038', 'Recognising these common physical signs helps clinical teams identify when a patient is likely entering the final hours to days of life, informing appropriate adjustments to the care plan and communication with family.', 1),
('f8000000-0000-0000-0000-000000000038', $x$These signs reflect the body's declining physiological function across multiple systems (neurological, respiratory, circulatory, renal) as part of the natural dying process, rather than indicating a specific reversible complication requiring active treatment.$x$, 2),
('f8000000-0000-0000-0000-000000000038', 'Sharing this information sensitively with family members can help them understand and prepare for what to expect, an important part of supporting families through this experience, alongside appropriate ongoing symptom management for the patient.', 3),
('f8000000-0000-0000-0000-000000000039', 'The oral-to-subcutaneous morphine conversion ratio of approximately 2:1 reflects the reduced first-pass metabolism and higher bioavailability of the subcutaneous route compared with oral administration.', 1),
('f8000000-0000-0000-0000-000000000039', 'Accurate opioid conversion calculations are essential for patient safety, as errors can result in either inadequate pain control (underdosing) or serious toxicity (overdosing).', 2),
('f8000000-0000-0000-0000-000000000039', 'This conversion principle (accounting for bioavailability differences between routes) is a general concept applicable across different opioid conversions, though specific ratios vary between different opioid drugs and route combinations.', 3),
('f8000000-0000-0000-0000-000000000040', 'The delayed onset (and equally delayed offset) of transdermal fentanyl is a specific, important pharmacokinetic consideration distinguishing it from oral opioid switches, where transitions can generally occur more promptly.', 1),
('f8000000-0000-0000-0000-000000000040', 'Appropriate overlap planning during this transition period is essential to avoid a gap in effective pain control, reflecting careful, safe practice when switching between different opioid routes and formulations.', 2),
('f8000000-0000-0000-0000-000000000040', 'Understanding these route-specific pharmacokinetic differences is important for safe, effective opioid prescribing across the range of formulations used in palliative care.', 3),
('f8000000-0000-0000-0000-000000000041', 'The one-sixth rule provides a standard, evidence-based starting point for breakthrough dose calculation, though doses may be further individually titrated based on response and effectiveness.', 1),
('f8000000-0000-0000-0000-000000000041', 'Tracking how frequently breakthrough doses are needed provides useful information for reviewing whether the background regular dose itself requires adjustment.', 2),
('f8000000-0000-0000-0000-000000000041', 'This calculation approach applies the same underlying principle regardless of which specific opioid or route is being used for the background regimen, adapted to the relevant total daily dose.', 3),
('f8000000-0000-0000-0000-000000000042', 'Compatibility reference guidance (charts/resources specifically developed for common syringe driver medication combinations) is an essential practical tool for safely combining multiple drugs in this way.', 1),
('f8000000-0000-0000-0000-000000000042', 'Physical incompatibility (visible precipitation, crystallisation, discolouration) can sometimes be directly observed, but chemical incompatibility (affecting drug stability/efficacy without visible change) may not be apparent without reference to established compatibility data.', 2),
('f8000000-0000-0000-0000-000000000042', 'This careful attention to compatibility reflects the broader principle of safe, evidence-based prescribing practice in palliative care, particularly relevant given the frequent need to combine multiple symptom-control medications via this route in patients unable to take oral medication.', 3),
('f8000000-0000-0000-0000-000000000043', 'Incomplete cross-tolerance between different opioids means a patient tolerant to one opioid may not have the same degree of tolerance to an equianalgesic dose of a different opioid, explaining the rationale for a cautious dose reduction during rotation.', 1),
('f8000000-0000-0000-0000-000000000043', 'The degree of dose reduction applied can vary depending on the specific opioids involved, the reason for switching, and clinical judgement, reflecting a degree of individualisation in this process.', 2),
('f8000000-0000-0000-0000-000000000043', 'Opioid rotation is a valuable technique for managing situations where pain control is adequate but side effects are problematic, or where pain control itself is inadequate despite dose escalation, offering a way to potentially improve the overall therapeutic balance.', 3),
('f8000000-0000-0000-0000-000000000044', 'Correctly calculating the total 24-hour background dose (accounting for twice-daily or other dosing frequencies) is the essential first step before applying the one-sixth breakthrough dose calculation.', 1),
('f8000000-0000-0000-0000-000000000044', 'This worked example demonstrates the practical application of the standard breakthrough dose calculation principle to a specific, common clinical dosing scenario.', 2),
('f8000000-0000-0000-0000-000000000044', 'Providing an appropriately calculated breakthrough dose, alongside the regular background opioid, ensures patients have effective options for managing pain flares between their scheduled doses.', 3),
('f8000000-0000-0000-0000-000000000045', 'Frequent breakthrough dose use is a key clinical indicator prompting review and likely upward adjustment of the background (syringe driver) opioid dose, reflecting ongoing, iterative titration based on actual patient response and requirement.', 1),
('f8000000-0000-0000-0000-000000000045', 'Recalculating the breakthrough dose based on the new, higher total daily dose ensures the breakthrough dosing remains appropriately proportionate as the overall regimen is adjusted.', 2),
('f8000000-0000-0000-0000-000000000045', $x$This process of ongoing review and recalculation reflects the dynamic, responsive nature of effective opioid titration in palliative care, adapting to the patient's changing pain control needs over time.$x$, 3),
('f8000000-0000-0000-0000-000000000046', 'Understanding that the general principle of reduced oral bioavailability (requiring dose reduction when switching to a more bioavailable parenteral route) applies across multiple opioids, though specific ratios can vary between different individual drugs.', 1),
('f8000000-0000-0000-0000-000000000046', 'Using accurate, up-to-date reference guidance for specific conversion ratios is important, as recommended ratios can be refined over time or vary slightly between different reputable sources.', 2),
('f8000000-0000-0000-0000-000000000046', 'Familiarity with conversion principles for commonly used opioids (morphine, oxycodone, and others) supports safe, confident prescribing across the range of formulations used in palliative care practice.', 3),
('f8000000-0000-0000-0000-000000000047', 'Understanding the specific metabolic pathway of each opioid (and whether active metabolites are renally dependent for clearance) is key to selecting an appropriate, safer option in significant renal impairment.', 1),
('f8000000-0000-0000-0000-000000000047', $x$Alfentanil's metabolic profile, without clinically significant renally-dependent active metabolites, makes it a commonly favoured choice for syringe driver use in patients with significant renal impairment in the palliative care context.$x$, 2),
('f8000000-0000-0000-0000-000000000047', 'Given the complexity of opioid pharmacokinetics in organ impairment, specialist palliative care or pharmacy input is often valuable to guide the safest, most effective choice and dosing strategy for individual patients.', 3),
('f8000000-0000-0000-0000-000000000048', 'Regular monitoring of subcutaneous infusion sites is an important, routine part of syringe driver management, allowing early identification and management of site reactions.', 1),
('f8000000-0000-0000-0000-000000000048', 'Site reactions can sometimes relate to the specific drug combination, concentration, or duration a site has been used, informing practical adjustments (e.g. more frequent site rotation) to reduce recurrence.', 2),
('f8000000-0000-0000-0000-000000000048', 'Prompt resiting maintains both patient comfort and the reliability of continued medication delivery, both important considerations in ongoing syringe driver management.', 3),
('f8000000-0000-0000-0000-000000000049', 'The skin depot effect of transdermal fentanyl means its offset (as well as its onset) is notably slower than most other opioid formulations, a key pharmacokinetic property relevant to route switching in either direction.', 1),
('f8000000-0000-0000-0000-000000000049', 'Careful timing, sometimes with initial dose reduction of the newly started opioid, helps avoid the risk of combined toxicity from overlapping fentanyl absorption and the new medication during this transition period.', 2),
('f8000000-0000-0000-0000-000000000049', 'Specialist palliative care guidance or resources are often valuable for navigating these more complex route switches safely, given the specific pharmacokinetic considerations involved.', 3),
('f8000000-0000-0000-0000-000000000050', 'Increasing drowsiness combined with respiratory depression (slow, shallow breathing) is a concerning combination specifically suggestive of opioid toxicity, requiring prompt clinical assessment rather than being assumed to be routine, expected sedation.', 1),
('f8000000-0000-0000-0000-000000000050', 'Identifying and addressing any potentially reversible contributing factors (declining renal function affecting opioid clearance, interacting sedating medications) alongside the immediate infusion adjustment supports a thorough, safe response.', 2),
('f8000000-0000-0000-0000-000000000050', 'This scenario illustrates the importance of ongoing clinical monitoring and prompt reassessment of patients on continuous opioid infusions, balancing effective symptom control against vigilance for toxicity.', 3);
